insert into public.questions (id, technology, difficulty, question, code, options, correct_index, explanation, xp_reward) values
  ('html-01', 'html', 'easy', '{"uz":"Saytning asosiy navigatsiya havolalari uchun qaysi semantik teg to‘g‘ri?","ru":"Какой семантический тег правильно использовать для основной навигации сайта?","en":"Which semantic tag is correct for the main navigation links of a site?"}'::jsonb, null, '[{"uz":"<navigation>","ru":"<navigation>","en":"<navigation>"},{"uz":"<nav>","ru":"<nav>","en":"<nav>"},{"uz":"<menu>","ru":"<menu>","en":"<menu>"},{"uz":"<div class=\"nav\">","ru":"<div class=\"nav\">","en":"<div class=\"nav\">"}]'::jsonb, 1, '{"uz":"<nav> — navigatsiya bloklari uchun mo‘ljallangan semantik teg. Ekran o‘quvchilar uni “navigation” landmark sifatida taniydi. <navigation> degan teg mavjud emas.","ru":"<nav> — семантический тег для навигационных блоков. Скринридеры распознают его как landmark «navigation». Тега <navigation> не существует.","en":"<nav> is the semantic element for navigation blocks. Screen readers expose it as a \"navigation\" landmark. There is no <navigation> element."}'::jsonb, 10),
  ('html-02', 'html', 'easy', '{"uz":"<!DOCTYPE html> deklaratsiyasi nima qiladi?","ru":"Что делает объявление <!DOCTYPE html>?","en":"What does the <!DOCTYPE html> declaration do?"}'::jsonb, null, '[{"uz":"HTML faylni JavaScript’ga ulaydi","ru":"Подключает HTML-файл к JavaScript","en":"Connects the HTML file to JavaScript"},{"uz":"Sahifa kodirovkasini UTF-8 qilib belgilaydi","ru":"Устанавливает кодировку страницы UTF-8","en":"Sets the page encoding to UTF-8"},{"uz":"Brauzerni standart rejimda (standards mode) ishlashga majbur qiladi","ru":"Переводит браузер в стандартный режим (standards mode)","en":"Makes the browser render the page in standards mode"},{"uz":"Sahifani qidiruv tizimlaridan yashiradi","ru":"Скрывает страницу от поисковых систем","en":"Hides the page from search engines"}]'::jsonb, 2, '{"uz":"DOCTYPE bo‘lmasa, brauzer “quirks mode”ga o‘tadi va eski, nostandart render qoidalarini qo‘llaydi. Kodirovka <meta charset=\"UTF-8\"> bilan belgilanadi.","ru":"Без DOCTYPE браузер переходит в «quirks mode» и использует устаревшие нестандартные правила рендеринга. Кодировка задаётся через <meta charset=\"UTF-8\">.","en":"Without a DOCTYPE the browser falls back to \"quirks mode\" with legacy, non‑standard rendering rules. Encoding is set by <meta charset=\"UTF-8\">."}'::jsonb, 10),
  ('html-03', 'html', 'easy', '{"uz":"Rasm uchun muqobil (alternativ) matn qaysi atribut orqali beriladi?","ru":"Какой атрибут задаёт альтернативный текст для изображения?","en":"Which attribute provides alternative text for an image?"}'::jsonb, null, '[{"uz":"alt","ru":"alt","en":"alt"},{"uz":"title","ru":"title","en":"title"},{"uz":"caption","ru":"caption","en":"caption"},{"uz":"aria-image","ru":"aria-image","en":"aria-image"}]'::jsonb, 0, '{"uz":"alt atributi rasm yuklanmaganda ko‘rsatiladi va ekran o‘quvchilar tomonidan o‘qiladi. Dekorativ rasmlar uchun alt=\"\" qo‘yiladi.","ru":"Атрибут alt отображается, если изображение не загрузилось, и зачитывается скринридерами. Для декоративных картинок используют alt=\"\".","en":"alt is shown when the image fails to load and is read by screen readers. Decorative images should use alt=\"\"."}'::jsonb, 10),
  ('html-04', 'html', 'medium', '{"uz":"<article> tegi qachon ishlatilishi kerak?","ru":"Когда следует использовать тег <article>?","en":"When should the <article> element be used?"}'::jsonb, null, '[{"uz":"Har qanday matnli blok uchun","ru":"Для любого текстового блока","en":"For any block of text"},{"uz":"Faqat sahifaning pastki qismi uchun","ru":"Только для подвала страницы","en":"Only for the page footer"},{"uz":"Stillar berish uchun o‘ram (wrapper) sifatida","ru":"Как обёртку для стилизации","en":"As a wrapper for styling purposes"},{"uz":"Mustaqil ma’noga ega, alohida tarqatilishi mumkin bo‘lgan kontent uchun (post, yangilik, izoh)","ru":"Для самостоятельного контента, который можно распространять отдельно (пост, новость, комментарий)","en":"For self-contained content that could be distributed independently (post, news item, comment)"}]'::jsonb, 3, '{"uz":"<article> — o‘z-o‘zidan tushunarli, mustaqil kontent. <section> esa sarlavhaga ega tematik guruh. Faqat stil uchun <div> ishlatiladi.","ru":"<article> — самодостаточный, независимый контент. <section> — тематическая группа с заголовком. Для обёртки ради стилей используют <div>.","en":"<article> is self-contained, independent content. <section> is a thematic grouping, usually with a heading. Use <div> for styling-only wrappers."}'::jsonb, 15),
  ('html-05', 'html', 'medium', '{"uz":"defer atributli skriptlar qanday bajariladi?","ru":"Как выполняются скрипты с атрибутом defer?","en":"How are scripts with the defer attribute executed?"}'::jsonb, '<script defer src="a.js"></script>
<script defer src="b.js"></script>', '[{"uz":"Yuklanishi bilanoq, HTML parsingni to‘xtatib","ru":"Сразу после загрузки, блокируя парсинг HTML","en":"As soon as they load, blocking HTML parsing"},{"uz":"HTML to‘liq parse qilingandan keyin, hujjatdagi tartibda","ru":"После полного парсинга HTML, в порядке следования в документе","en":"After HTML parsing finishes, in document order"},{"uz":"Yuklanishi bilanoq, istalgan tartibda","ru":"Сразу после загрузки, в произвольном порядке","en":"As soon as they load, in any order"},{"uz":"Faqat foydalanuvchi sahifani skroll qilganda","ru":"Только когда пользователь прокручивает страницу","en":"Only when the user scrolls the page"}]'::jsonb, 1, '{"uz":"defer skriptlari parallel yuklanadi, lekin DOMContentLoaded’dan oldin hujjatdagi tartibda bajariladi. async esa yuklanishi bilan, tartibsiz bajariladi.","ru":"defer-скрипты загружаются параллельно, но выполняются по порядку перед DOMContentLoaded. async выполняются сразу после загрузки, без гарантии порядка.","en":"defer scripts download in parallel but run in order right before DOMContentLoaded. async scripts run as soon as they load, in no guaranteed order."}'::jsonb, 15),
  ('html-06', 'html', 'easy', '{"uz":"Qaysi input turi brauzerda email formatini avtomatik tekshiradi?","ru":"Какой тип input автоматически проверяет формат email в браузере?","en":"Which input type gets built-in email format validation in the browser?"}'::jsonb, null, '[{"uz":"type=\"text\"","ru":"type=\"text\"","en":"type=\"text\""},{"uz":"type=\"mail\"","ru":"type=\"mail\"","en":"type=\"mail\""},{"uz":"type=\"email\"","ru":"type=\"email\"","en":"type=\"email\""},{"uz":"type=\"address\"","ru":"type=\"address\"","en":"type=\"address\""}]'::jsonb, 2, '{"uz":"type=\"email\" brauzerning o‘rnatilgan validatsiyasini yoqadi va mobil qurilmalarda “@” belgili klaviaturani ochadi. type=\"mail\" mavjud emas.","ru":"type=\"email\" включает встроенную валидацию браузера и открывает клавиатуру с «@» на мобильных. type=\"mail\" не существует.","en":"type=\"email\" enables built-in validation and shows an \"@\" keyboard on mobile devices. type=\"mail\" does not exist."}'::jsonb, 10),
  ('html-07', 'html', 'medium', '{"uz":"data-* atributlari nima uchun ishlatiladi?","ru":"Для чего используются атрибуты data-*?","en":"What are data-* attributes used for?"}'::jsonb, '<li data-user-id="42">Ali</li>
// el.dataset.userId === "42"', '[{"uz":"Elementda qo‘shimcha maxsus ma’lumot saqlash uchun, JS’da dataset orqali o‘qiladi","ru":"Для хранения пользовательских данных на элементе, доступных в JS через dataset","en":"To store custom data on an element, readable in JS via dataset"},{"uz":"Serverga ma’lumot yuborish uchun","ru":"Для отправки данных на сервер","en":"To send data to the server"},{"uz":"Elementni ekran o‘quvchilardan yashirish uchun","ru":"Чтобы скрыть элемент от скринридеров","en":"To hide the element from screen readers"},{"uz":"Ma’lumotlar bazasiga ulanish uchun","ru":"Для подключения к базе данных","en":"To connect to a database"}]'::jsonb, 0, '{"uz":"data-* — HTML elementiga maxsus ma’lumot biriktirishning standart usuli. Kebab-case nomlar dataset’da camelCase’ga aylanadi (data-user-id → dataset.userId).","ru":"data-* — стандартный способ прикрепить к элементу свои данные. Kebab-case имена превращаются в camelCase в dataset (data-user-id → dataset.userId).","en":"data-* is the standard way to attach custom data to an element. Kebab-case names become camelCase in dataset (data-user-id → dataset.userId)."}'::jsonb, 15),
  ('html-08', 'html', 'medium', '{"uz":"<label> elementidagi for atributi nima qiladi?","ru":"Что делает атрибут for у элемента <label>?","en":"What does the for attribute on a <label> do?"}'::jsonb, '<label for="email">Email</label>
<input id="email" type="email" />', '[{"uz":"Labelni sikl (loop) ichida takrorlaydi","ru":"Повторяет label в цикле","en":"Repeats the label in a loop"},{"uz":"Input qiymatini avtomatik to‘ldiradi","ru":"Автоматически заполняет значение input","en":"Auto-fills the input value"},{"uz":"Labelga CSS klass qo‘shadi","ru":"Добавляет label CSS-класс","en":"Adds a CSS class to the label"},{"uz":"Labelni id orqali inputga bog‘laydi: label bosilganda input fokuslanadi va u ekran o‘quvchiga nom beradi","ru":"Связывает label с input по id: клик по label фокусирует поле, и скринридер получает его имя","en":"Associates the label with the input by id: clicking the label focuses the input and gives it an accessible name"}]'::jsonb, 3, '{"uz":"for=\"email\" label’ni id=\"email\" bo‘lgan boshqaruv elementiga bog‘laydi. Bu accessibility uchun muhim va bosish maydonini kattalashtiradi.","ru":"for=\"email\" связывает label с контролом id=\"email\". Это важно для доступности и увеличивает область клика.","en":"for=\"email\" links the label to the control with id=\"email\". This is essential for accessibility and enlarges the click target."}'::jsonb, 15),
  ('html-09', 'html', 'easy', '{"uz":"Quyidagilardan qaysi biri sukut bo‘yicha inline element hisoblanadi?","ru":"Какой из перечисленных элементов по умолчанию является строчным (inline)?","en":"Which of these elements is inline by default?"}'::jsonb, null, '[{"uz":"<div>","ru":"<div>","en":"<div>"},{"uz":"<span>","ru":"<span>","en":"<span>"},{"uz":"<p>","ru":"<p>","en":"<p>"},{"uz":"<section>","ru":"<section>","en":"<section>"}]'::jsonb, 1, '{"uz":"<span> — inline element, u yangi qatordan boshlanmaydi va faqat kontent kengligini egallaydi. <div>, <p>, <section> — blok elementlar.","ru":"<span> — строчный элемент: не начинается с новой строки и занимает ширину содержимого. <div>, <p>, <section> — блочные.","en":"<span> is inline: it does not start on a new line and only takes the width of its content. <div>, <p> and <section> are block elements."}'::jsonb, 10),
  ('html-10', 'html', 'hard', '{"uz":"<form> ichidagi type atributisiz <button> bosilsa nima bo‘ladi?","ru":"Что произойдёт при клике на <button> без атрибута type внутри <form>?","en":"What happens when a <button> without a type attribute inside a <form> is clicked?"}'::jsonb, '<form action="/save">
  <input name="title" />
  <button>Preview</button>
</form>', '[{"uz":"Hech narsa, tugma sukut bo‘yicha type=\"button\"","ru":"Ничего, по умолчанию type=\"button\"","en":"Nothing, the default is type=\"button\""},{"uz":"Forma tozalanadi (reset)","ru":"Форма сбросится (reset)","en":"The form is reset"},{"uz":"Forma yuboriladi, chunki sukut bo‘yicha type=\"submit\"","ru":"Форма отправится, так как по умолчанию type=\"submit\"","en":"The form is submitted because the default type is \"submit\""},{"uz":"Brauzer xato chiqaradi","ru":"Браузер выдаст ошибку","en":"The browser throws an error"}]'::jsonb, 2, '{"uz":"Forma ichidagi <button> sukut bo‘yicha submit tugmasi. Yuborishni xohlamasangiz, type=\"button\" ni aniq yozing — bu ko‘p uchraydigan xato.","ru":"У <button> внутри формы тип по умолчанию — submit. Если отправка не нужна, явно укажите type=\"button\" — это частая ошибка.","en":"A <button> inside a form defaults to type=\"submit\". If you do not want to submit, set type=\"button\" explicitly — a very common bug."}'::jsonb, 20),
  ('html-11', 'html', 'easy', '{"uz":"Mobil qurilmalarda responsive dizayn to‘g‘ri ishlashi uchun qaysi meta-teg kerak?","ru":"Какой meta-тег нужен для корректной адаптивной вёрстки на мобильных устройствах?","en":"Which meta tag is required for responsive layouts to work correctly on mobile devices?"}'::jsonb, null, '[{"uz":"<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">","ru":"<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">","en":"<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">"},{"uz":"<meta name=\"mobile\" content=\"true\">","ru":"<meta name=\"mobile\" content=\"true\">","en":"<meta name=\"mobile\" content=\"true\">"},{"uz":"<meta http-equiv=\"responsive\" content=\"yes\">","ru":"<meta http-equiv=\"responsive\" content=\"yes\">","en":"<meta http-equiv=\"responsive\" content=\"yes\">"},{"uz":"<meta name=\"screen\" content=\"auto\">","ru":"<meta name=\"screen\" content=\"auto\">","en":"<meta name=\"screen\" content=\"auto\">"}]'::jsonb, 0, '{"uz":"Viewport meta-tegisiz mobil brauzer sahifani ~980px kenglikda chizadi va kichraytiradi, natijada media-so‘rovlar kutilgandek ishlamaydi.","ru":"Без meta viewport мобильный браузер рендерит страницу шириной ~980px и масштабирует её, из‑за чего медиазапросы работают не так, как ожидается.","en":"Without the viewport meta tag, mobile browsers render at ~980px wide and zoom out, so media queries do not behave as expected."}'::jsonb, 10),
  ('html-12', 'html', 'medium', '{"uz":"localStorage va sessionStorage o‘rtasidagi asosiy farq nima?","ru":"В чём основное различие между localStorage и sessionStorage?","en":"What is the main difference between localStorage and sessionStorage?"}'::jsonb, null, '[{"uz":"localStorage faqat raqamlarni saqlaydi","ru":"localStorage хранит только числа","en":"localStorage stores numbers only"},{"uz":"sessionStorage ma’lumotlarni serverga yuboradi","ru":"sessionStorage отправляет данные на сервер","en":"sessionStorage sends data to the server"},{"uz":"Ular orasida farq yo‘q","ru":"Разницы нет","en":"There is no difference"},{"uz":"sessionStorage tab yopilganda tozalanadi, localStorage esa o‘chirilmaguncha saqlanadi","ru":"sessionStorage очищается при закрытии вкладки, localStorage хранится до явного удаления","en":"sessionStorage is cleared when the tab closes; localStorage persists until explicitly removed"}]'::jsonb, 3, '{"uz":"Ikkalasi ham faqat satrlarni saqlaydi va serverga yuborilmaydi (cookie’dan farqli). sessionStorage bitta tab sessiyasiga bog‘langan.","ru":"Оба хранят только строки и не отправляются на сервер (в отличие от cookie). sessionStorage привязан к сессии одной вкладки.","en":"Both store strings only and are never sent to the server (unlike cookies). sessionStorage is scoped to a single tab session."}'::jsonb, 15),
  ('html-13', 'html', 'hard', '{"uz":"loading=\"lazy\" atributi <img> uchun nima qiladi?","ru":"Что делает атрибут loading=\"lazy\" у <img>?","en":"What does loading=\"lazy\" do on an <img>?"}'::jsonb, '<img src="photo.jpg" alt="Team" loading="lazy" width="600" height="400">', '[{"uz":"Rasmni past sifatda yuklaydi","ru":"Загружает изображение в низком качестве","en":"Loads the image in low quality"},{"uz":"Ekrandan tashqaridagi rasm yuklanishini u viewport’ga yaqinlashguncha kechiktiradi","ru":"Откладывает загрузку изображения вне экрана, пока оно не приблизится к viewport","en":"Defers loading an off-screen image until it gets close to the viewport"},{"uz":"Rasmni faqat bosilganda yuklaydi","ru":"Загружает изображение только по клику","en":"Loads the image only on click"},{"uz":"Rasmni keshga saqlashni taqiqlaydi","ru":"Запрещает кэширование изображения","en":"Prevents the image from being cached"}]'::jsonb, 1, '{"uz":"Native lazy loading trafik va dastlabki yuklanish vaqtini tejaydi. width/height berish layout siljishini (CLS) oldini oladi. Birinchi ekrandagi asosiy rasmga lazy qo‘ymang.","ru":"Нативная ленивая загрузка экономит трафик и время первой загрузки. width/height предотвращают сдвиг макета (CLS). Не ставьте lazy на главное изображение первого экрана.","en":"Native lazy loading saves bandwidth and initial load time. width/height prevent layout shift (CLS). Do not lazy-load the main above-the-fold image."}'::jsonb, 20),
  ('html-14', 'html', 'medium', '{"uz":"Izohli (caption) diagramma yoki rasm uchun qaysi teglar juftligi semantik jihatdan to‘g‘ri?","ru":"Какая пара тегов семантически верна для изображения или диаграммы с подписью?","en":"Which pair of elements is semantically correct for an image or diagram with a caption?"}'::jsonb, null, '[{"uz":"<div> + <span>","ru":"<div> + <span>","en":"<div> + <span>"},{"uz":"<picture> + <caption>","ru":"<picture> + <caption>","en":"<picture> + <caption>"},{"uz":"<figure> + <figcaption>","ru":"<figure> + <figcaption>","en":"<figure> + <figcaption>"},{"uz":"<img> + <label>","ru":"<img> + <label>","en":"<img> + <label>"}]'::jsonb, 2, '{"uz":"<figure> mustaqil illyustratsiyani, <figcaption> esa uning izohini bildiradi. <caption> faqat <table> uchun ishlatiladi.","ru":"<figure> обозначает самостоятельную иллюстрацию, <figcaption> — её подпись. <caption> используется только внутри <table>.","en":"<figure> marks self-contained illustrative content and <figcaption> its caption. <caption> is only valid inside <table>."}'::jsonb, 15),
  ('html-15', 'html', 'hard', '{"uz":"Nega bosiladigan boshqaruv elementi uchun <div onclick> o‘rniga native <button> afzal?","ru":"Почему для кликабельного элемента управления нативный <button> предпочтительнее <div onclick>?","en":"Why is a native <button> preferred over <div onclick> for a clickable control?"}'::jsonb, null, '[{"uz":"<button> tezroq render qilinadi","ru":"<button> быстрее рендерится","en":"<button> renders faster"},{"uz":"<div> ga onclick qo‘shib bo‘lmaydi","ru":"К <div> нельзя добавить onclick","en":"You cannot attach onclick to a <div>"},{"uz":"<button> avtomatik ravishda chiroyli stil oladi","ru":"<button> автоматически получает красивые стили","en":"<button> automatically gets nice styling"},{"uz":"<button> fokuslanadi, Enter/Space bilan ishlaydi va yordamchi texnologiyalarga “button” roli bilan ko‘rinadi","ru":"<button> фокусируется, работает с Enter/Space и виден вспомогательным технологиям с ролью «button»","en":"<button> is focusable, works with Enter/Space and is exposed to assistive tech with the \"button\" role"}]'::jsonb, 3, '{"uz":"<div> ni accessible qilish uchun role=\"button\", tabindex=\"0\" va klaviatura ishlovchilari kerak bo‘ladi. Native <button> bularning barchasini bepul beradi.","ru":"Чтобы сделать <div> доступным, нужны role=\"button\", tabindex=\"0\" и обработчики клавиатуры. Нативный <button> даёт всё это бесплатно.","en":"Making a <div> accessible requires role=\"button\", tabindex=\"0\" and keyboard handlers. A native <button> gives you all of this for free."}'::jsonb, 20),
  ('css-01', 'css', 'easy', '{"uz":"CSS box model qatlamlari ichkaridan tashqariga qanday tartibda joylashgan?","ru":"В каком порядке расположены слои CSS box model изнутри наружу?","en":"In what order are the CSS box model layers arranged from inside out?"}'::jsonb, null, '[{"uz":"margin → border → padding → content","ru":"margin → border → padding → content","en":"margin → border → padding → content"},{"uz":"content → padding → border → margin","ru":"content → padding → border → margin","en":"content → padding → border → margin"},{"uz":"content → border → padding → margin","ru":"content → border → padding → margin","en":"content → border → padding → margin"},{"uz":"padding → content → margin → border","ru":"padding → content → margin → border","en":"padding → content → margin → border"}]'::jsonb, 1, '{"uz":"Kontent atrofida ichki bo‘shliq (padding), keyin chegara (border), eng tashqarida esa tashqi bo‘shliq (margin) joylashadi.","ru":"Вокруг содержимого — внутренний отступ (padding), затем рамка (border), снаружи — внешний отступ (margin).","en":"Content is wrapped by padding, then the border, and the margin is the outermost layer."}'::jsonb, 10),
  ('css-02', 'css', 'easy', '{"uz":"box-sizing: border-box nimani anglatadi?","ru":"Что означает box-sizing: border-box?","en":"What does box-sizing: border-box mean?"}'::jsonb, '.card {
  box-sizing: border-box;
  width: 300px;
  padding: 20px;
  border: 2px solid;
}', '[{"uz":"width padding va border’ni ham o‘z ichiga oladi — element aynan 300px","ru":"width включает padding и border — элемент ровно 300px","en":"width includes padding and border — the element is exactly 300px"},{"uz":"Element kengligi 344px bo‘ladi","ru":"Ширина элемента будет 344px","en":"The element will be 344px wide"},{"uz":"Border ko‘rinmay qoladi","ru":"Рамка станет невидимой","en":"The border becomes invisible"},{"uz":"margin ham kenglikka qo‘shiladi","ru":"margin тоже входит в ширину","en":"margin is also included in the width"}]'::jsonb, 0, '{"uz":"border-box’da padding va border width ichida hisoblanadi. content-box’da (sukut bo‘yicha) kenglik 300 + 40 + 4 = 344px bo‘lardi. margin hech qachon kiritilmaydi.","ru":"При border-box padding и border входят в width. При content-box (по умолчанию) ширина была бы 300 + 40 + 4 = 344px. margin не входит никогда.","en":"With border-box, padding and border are inside width. With content-box (the default) it would be 300 + 40 + 4 = 344px. Margin is never included."}'::jsonb, 10),
  ('css-03', 'css', 'medium', '{"uz":"Sarlavha qanday rangda bo‘ladi?","ru":"Каким цветом будет заголовок?","en":"What color will the heading be?"}'::jsonb, '<h1 id="title" class="a b c">Hello</h1>

#title { color: red; }
.a.b.c { color: blue; }
h1 { color: green; }', '[{"uz":"Ko‘k — u keyinroq yozilgan","ru":"Синим — правило ниже","en":"Blue — it comes later"},{"uz":"Yashil — teg selektori","ru":"Зелёным — селектор тега","en":"Green — the tag selector"},{"uz":"Qizil — id selektori specificity’si yuqoriroq","ru":"Красным — у id-селектора выше специфичность","en":"Red — the id selector has higher specificity"},{"uz":"Qora — konflikt tufayli","ru":"Чёрным — из-за конфликта","en":"Black — because of the conflict"}]'::jsonb, 2, '{"uz":"Specificity: #id = (1,0,0), .a.b.c = (0,3,0), h1 = (0,0,1). Har qancha klass bo‘lsa ham bitta id’dan kuchli bo‘lmaydi; tartib faqat specificity teng bo‘lganda muhim.","ru":"Специфичность: #id = (1,0,0), .a.b.c = (0,3,0), h1 = (0,0,1). Никакое число классов не перебьёт один id; порядок важен только при равной специфичности.","en":"Specificity: #id = (1,0,0), .a.b.c = (0,3,0), h1 = (0,0,1). No number of classes beats one id; source order only matters on equal specificity."}'::jsonb, 15),
  ('css-04', 'css', 'easy', '{"uz":"position: absolute bo‘lgan element nimaga nisbatan joylashadi?","ru":"Относительно чего позиционируется элемент с position: absolute?","en":"An element with position: absolute is positioned relative to what?"}'::jsonb, null, '[{"uz":"Har doim brauzer oynasiga","ru":"Всегда относительно окна браузера","en":"Always the browser window"},{"uz":"Bevosita ota elementga, uning position qiymatidan qat’i nazar","ru":"Непосредственного родителя, независимо от его position","en":"Its direct parent, regardless of its position"},{"uz":"O‘zining odatiy joyiga","ru":"Своего обычного места в потоке","en":"Its normal place in the flow"},{"uz":"position: static bo‘lmagan eng yaqin ajdodga (bo‘lmasa — boshlang‘ich bloka)","ru":"Ближайшего предка с position, отличным от static (иначе — начального блока)","en":"The nearest ancestor whose position is not static (otherwise the initial containing block)"}]'::jsonb, 3, '{"uz":"Shuning uchun ota elementga odatda position: relative beriladi. Absolute element oqimdan chiqariladi va joy egallamaydi.","ru":"Поэтому родителю обычно задают position: relative. Абсолютный элемент выпадает из потока и не занимает места.","en":"That is why the parent is usually given position: relative. An absolute element is removed from the flow and takes no space."}'::jsonb, 10),
  ('css-05', 'css', 'medium', '{"uz":"flex-direction: row bo‘lgan flex-konteynerda justify-content qaysi o‘q bo‘yicha tekislaydi?","ru":"По какой оси выравнивает justify-content во flex-контейнере с flex-direction: row?","en":"In a flex container with flex-direction: row, along which axis does justify-content align items?"}'::jsonb, null, '[{"uz":"Ko‘ndalang (cross) o‘q — vertikal","ru":"Поперечная ось — вертикаль","en":"The cross axis — vertical"},{"uz":"Asosiy (main) o‘q — gorizontal","ru":"Главная ось — горизонталь","en":"The main axis — horizontal"},{"uz":"Ikkala o‘q bo‘yicha","ru":"По обеим осям","en":"Both axes"},{"uz":"Faqat matn bazaviy chizig‘i bo‘yicha","ru":"Только по базовой линии текста","en":"Only along the text baseline"}]'::jsonb, 1, '{"uz":"justify-content — asosiy o‘q, align-items — ko‘ndalang o‘q. flex-direction: column bo‘lsa, o‘qlar almashadi.","ru":"justify-content — главная ось, align-items — поперечная. При flex-direction: column оси меняются местами.","en":"justify-content works on the main axis, align-items on the cross axis. With flex-direction: column the axes swap."}'::jsonb, 15),
  ('css-06', 'css', 'medium', '{"uz":"display: none va visibility: hidden o‘rtasidagi farq nima?","ru":"В чём разница между display: none и visibility: hidden?","en":"What is the difference between display: none and visibility: hidden?"}'::jsonb, null, '[{"uz":"visibility: hidden element joyini saqlab qoladi, display: none esa uni oqimdan butunlay olib tashlaydi","ru":"visibility: hidden сохраняет место элемента, display: none полностью убирает его из потока","en":"visibility: hidden keeps the element''s space, display: none removes it from the layout entirely"},{"uz":"Ular bir xil ishlaydi","ru":"Они работают одинаково","en":"They behave the same"},{"uz":"display: none elementni DOM’dan o‘chiradi","ru":"display: none удаляет элемент из DOM","en":"display: none deletes the element from the DOM"},{"uz":"visibility: hidden faqat matnni yashiradi","ru":"visibility: hidden скрывает только текст","en":"visibility: hidden only hides text"}]'::jsonb, 0, '{"uz":"Ikkala holatda ham element DOM’da qoladi. display: none layout’dan chiqaradi; visibility: hidden ko‘rinmas, lekin joy egallaydi.","ru":"В обоих случаях элемент остаётся в DOM. display: none убирает его из раскладки; visibility: hidden — невидим, но занимает место.","en":"In both cases the element stays in the DOM. display: none removes it from layout; visibility: hidden is invisible but still occupies space."}'::jsonb, 15),
  ('css-07', 'css', 'easy', '{"uz":"rem birligi nimaga nisbatan hisoblanadi?","ru":"Относительно чего вычисляется единица rem?","en":"What is the rem unit relative to?"}'::jsonb, null, '[{"uz":"Ota elementning shrift o‘lchamiga","ru":"Размера шрифта родителя","en":"The parent''s font size"},{"uz":"Viewport kengligiga","ru":"Ширины viewport","en":"The viewport width"},{"uz":"Ildiz (html) elementning shrift o‘lchamiga","ru":"Размера шрифта корневого элемента (html)","en":"The root (html) element''s font size"},{"uz":"Ekran piksel zichligiga","ru":"Плотности пикселей экрана","en":"The screen pixel density"}]'::jsonb, 2, '{"uz":"rem — “root em”. html’da 16px bo‘lsa, 1.5rem = 24px. em esa joriy elementning shrift o‘lchamiga bog‘liq va ichma-ich ko‘payib ketishi mumkin.","ru":"rem — «root em». Если у html 16px, то 1.5rem = 24px. em зависит от размера шрифта текущего элемента и может накапливаться при вложенности.","en":"rem means \"root em\". With 16px on html, 1.5rem = 24px. em depends on the current element''s font size and compounds when nested."}'::jsonb, 10),
  ('css-08', 'css', 'easy', '{"uz":"Bu kod qanday grid yaratadi?","ru":"Какую сетку создаёт этот код?","en":"What grid does this code create?"}'::jsonb, '.grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 16px;
}', '[{"uz":"3 ta qator","ru":"3 строки","en":"3 rows"},{"uz":"Bo‘sh joyni teng bo‘luvchi 3 ta teng ustun","ru":"3 равные колонки, делящие свободное место","en":"3 equal columns sharing the free space"},{"uz":"Har biri 1px kenglikdagi 3 ta ustun","ru":"3 колонки шириной 1px","en":"3 columns 1px wide each"},{"uz":"Kontentga qarab har xil kenglikdagi ustunlar","ru":"Колонки разной ширины по содержимому","en":"Columns of varying width based on content"}]'::jsonb, 1, '{"uz":"fr — bo‘sh joyning ulushi. repeat(3, 1fr) = 1fr 1fr 1fr, gap esa ustunlar orasidagi masofani beradi.","ru":"fr — доля свободного пространства. repeat(3, 1fr) = 1fr 1fr 1fr, а gap задаёт промежутки между колонками.","en":"fr is a fraction of the free space. repeat(3, 1fr) equals 1fr 1fr 1fr and gap sets the spacing between tracks."}'::jsonb, 10),
  ('css-09', 'css', 'hard', '{"uz":".child nega .overlay ustida ko‘rinmaydi?","ru":"Почему .child не отображается поверх .overlay?","en":"Why does .child not appear above .overlay?"}'::jsonb, '.parent  { position: relative; z-index: 1; }
.child   { position: absolute; z-index: 999; }
.overlay { position: fixed; z-index: 2; }

<div class="parent"><div class="child"></div></div>
<div class="overlay"></div>', '[{"uz":"z-index 999 dan katta bo‘lishi mumkin emas","ru":"z-index не может быть больше 999","en":"z-index cannot be larger than 999"},{"uz":"absolute elementlarda z-index ishlamaydi","ru":"z-index не работает у absolute-элементов","en":"z-index does not work on absolute elements"},{"uz":"fixed elementlar har doim eng yuqorida bo‘ladi","ru":"fixed-элементы всегда сверху","en":"fixed elements are always on top"},{"uz":".parent o‘z stacking context’ini yaratgan, .child faqat uning ichida tartiblanadi (1 < 2)","ru":".parent создал свой контекст наложения, и .child упорядочивается только внутри него (1 < 2)","en":".parent creates its own stacking context, so .child is only ordered inside it (1 < 2)"}]'::jsonb, 3, '{"uz":"position + z-index yangi stacking context hosil qiladi. Bola elementning z-index’i faqat ota konteksti ichida ta’sir qiladi, tashqarida esa ota z-index: 1 bilan solishtiriladi.","ru":"position + z-index создают новый контекст наложения. z-index потомка действует только внутри контекста родителя, а снаружи сравнивается z-index: 1 родителя.","en":"position + z-index creates a new stacking context. A child''s z-index only applies within the parent''s context; outside, the parent''s z-index: 1 is what is compared."}'::jsonb, 20),
  ('css-10', 'css', 'medium', '{"uz":"Quyidagilardan qaysi biri pseudo-element?","ru":"Что из перечисленного является псевдоэлементом?","en":"Which of the following is a pseudo-element?"}'::jsonb, null, '[{"uz":"::before","ru":"::before","en":"::before"},{"uz":":hover","ru":":hover","en":":hover"},{"uz":":first-child","ru":":first-child","en":":first-child"},{"uz":":focus-visible","ru":":focus-visible","en":":focus-visible"}]'::jsonb, 0, '{"uz":"Pseudo-elementlar (::before, ::after, ::placeholder) elementning qismini yoki virtual elementni stillaydi. Pseudo-klasslar (:hover, :first-child) esa holat yoki pozitsiyani tanlaydi.","ru":"Псевдоэлементы (::before, ::after, ::placeholder) стилизуют часть элемента или виртуальный элемент. Псевдоклассы (:hover, :first-child) выбирают состояние или позицию.","en":"Pseudo-elements (::before, ::after, ::placeholder) style a part of an element or a virtual element. Pseudo-classes (:hover, :first-child) select a state or position."}'::jsonb, 15),
  ('css-11', 'css', 'hard', '{"uz":"Ikki blok orasidagi vertikal masofa qancha bo‘ladi?","ru":"Каким будет вертикальное расстояние между блоками?","en":"What will the vertical distance between the two blocks be?"}'::jsonb, '<div class="a"></div>
<div class="b"></div>

.a { margin-bottom: 20px; }
.b { margin-top: 30px; }', '[{"uz":"50px","ru":"50px","en":"50px"},{"uz":"20px","ru":"20px","en":"20px"},{"uz":"30px","ru":"30px","en":"30px"},{"uz":"25px","ru":"25px","en":"25px"}]'::jsonb, 2, '{"uz":"Margin collapse: oddiy blok oqimida qo‘shni elementlarning vertikal marginlari qo‘shilmaydi, kattasi olinadi. Flex/grid elementlarida bu sodir bo‘lmaydi.","ru":"Схлопывание margin: в обычном блочном потоке вертикальные отступы соседей не складываются, берётся больший. Во flex/grid этого не происходит.","en":"Margin collapsing: in normal block flow, adjacent vertical margins do not add up — the larger one wins. It does not happen for flex/grid items."}'::jsonb, 20),
  ('css-12', 'css', 'medium', '{"uz":"position: sticky qanday ishlaydi?","ru":"Как работает position: sticky?","en":"How does position: sticky work?"}'::jsonb, '.header {
  position: sticky;
  top: 0;
}', '[{"uz":"Har doim ekranning yuqorisida qotib turadi","ru":"Всегда закреплён вверху экрана","en":"Always fixed to the top of the screen"},{"uz":"Belgilangan chegaraga (top: 0) yetguncha relative, keyin konteyneri ichida fixed kabi yopishadi","ru":"Ведёт себя как relative до порога (top: 0), затем «прилипает» как fixed в пределах контейнера","en":"Behaves as relative until the threshold (top: 0), then sticks like fixed within its container"},{"uz":"Elementni oqimdan chiqaradi","ru":"Выводит элемент из потока","en":"Removes the element from the flow"},{"uz":"Faqat flex konteynerda ishlaydi","ru":"Работает только во flex-контейнере","en":"Only works inside a flex container"}]'::jsonb, 1, '{"uz":"Sticky element oqimdagi joyini saqlaydi va faqat o‘z ota konteyneri chegarasida yopishadi. Ota elementda overflow: hidden bo‘lsa, ko‘pincha ishlamay qoladi.","ru":"Sticky-элемент сохраняет место в потоке и «липнет» только в пределах родителя. Часто ломается, если у предка overflow: hidden.","en":"A sticky element keeps its place in the flow and only sticks within its parent. It often breaks when an ancestor has overflow: hidden."}'::jsonb, 15),
  ('css-13', 'css', 'hard', '{"uz":"Silliq animatsiya uchun qaysi xususiyatlarni animatsiya qilish eng arzon (layout/paint qayta hisoblanmaydi)?","ru":"Какие свойства дешевле всего анимировать для плавности (без пересчёта layout/paint)?","en":"Which properties are cheapest to animate smoothly (no layout/paint recalculation)?"}'::jsonb, null, '[{"uz":"width, height","ru":"width, height","en":"width, height"},{"uz":"top, left","ru":"top, left","en":"top, left"},{"uz":"margin, padding","ru":"margin, padding","en":"margin, padding"},{"uz":"transform, opacity","ru":"transform, opacity","en":"transform, opacity"}]'::jsonb, 3, '{"uz":"transform va opacity odatda compositor’da GPU yordamida bajariladi. width/top/margin har kadrda layout’ni qayta hisoblashga majbur qiladi.","ru":"transform и opacity обычно обрабатываются композитором на GPU. width/top/margin заставляют пересчитывать layout на каждом кадре.","en":"transform and opacity are usually handled by the compositor on the GPU. width/top/margin force layout recalculation on every frame."}'::jsonb, 20),
  ('css-14', 'css', 'medium', '{"uz":"Mobile-first yondashuvda odatda qanday media-so‘rov ishlatiladi?","ru":"Какой медиазапрос обычно используют при подходе mobile-first?","en":"Which media query is typically used in a mobile-first approach?"}'::jsonb, null, '[{"uz":"@media (min-width: 768px) { ... }","ru":"@media (min-width: 768px) { ... }","en":"@media (min-width: 768px) { ... }"},{"uz":"@media (max-width: 768px) { ... }","ru":"@media (max-width: 768px) { ... }","en":"@media (max-width: 768px) { ... }"},{"uz":"@media (orientation: mobile) { ... }","ru":"@media (orientation: mobile) { ... }","en":"@media (orientation: mobile) { ... }"},{"uz":"@media screen and (device: phone) { ... }","ru":"@media screen and (device: phone) { ... }","en":"@media screen and (device: phone) { ... }"}]'::jsonb, 0, '{"uz":"Mobile-first’da asosiy stillar mobil uchun yoziladi, kattaroq ekranlar uchun esa min-width bilan kengaytiriladi. max-width — desktop-first yondashuvi.","ru":"При mobile-first базовые стили пишутся для мобильных, а для больших экранов расширяются через min-width. max-width — подход desktop-first.","en":"Mobile-first writes base styles for small screens and enhances for larger ones with min-width. max-width is the desktop-first approach."}'::jsonb, 15),
  ('css-15', 'css', 'hard', '{"uz":":is() va :where() o‘rtasidagi asosiy farq nima?","ru":"В чём главное различие между :is() и :where()?","en":"What is the key difference between :is() and :where()?"}'::jsonb, ':is(#main, .card) p { color: red; }
:where(#main, .card) p { color: blue; }', '[{"uz":":where() faqat id’larni qabul qiladi","ru":":where() принимает только id","en":":where() only accepts ids"},{"uz":":is() eski brauzerlarda ishlamaydi, :where() ishlaydi","ru":":is() не работает в старых браузерах, а :where() работает","en":":is() does not work in old browsers but :where() does"},{"uz":":where() har doim 0 specificity’ga ega, :is() esa argumentlardagi eng yuqori specificity’ni oladi","ru":":where() всегда имеет нулевую специфичность, :is() берёт наибольшую специфичность аргументов","en":":where() always has zero specificity, while :is() takes the specificity of its most specific argument"},{"uz":"Ular mutlaqo bir xil","ru":"Они полностью одинаковы","en":"They are completely identical"}]'::jsonb, 2, '{"uz":"Shu sababli :where() kutubxona/reset stillari uchun qulay — ularni oson qayta yozish mumkin. Yuqoridagi misolda :is() varianti id specificity’sini oladi.","ru":"Поэтому :where() удобен для библиотечных и reset-стилей — их легко переопределить. В примере вариант с :is() получает специфичность id.","en":"That makes :where() great for library/reset styles that should be easy to override. In the example the :is() rule gets id-level specificity."}'::jsonb, 20),
  ('js-01', 'javascript', 'easy', '{"uz":"typeof null nimani qaytaradi?","ru":"Что вернёт typeof null?","en":"What does typeof null return?"}'::jsonb, null, '[{"uz":"\"null\"","ru":"\"null\"","en":"\"null\""},{"uz":"\"object\"","ru":"\"object\"","en":"\"object\""},{"uz":"\"undefined\"","ru":"\"undefined\"","en":"\"undefined\""},{"uz":"\"number\"","ru":"\"number\"","en":"\"number\""}]'::jsonb, 1, '{"uz":"Bu JavaScript’ning tarixiy xatosi: typeof null === \"object\". null’ni tekshirish uchun value === null ishlating.","ru":"Это историческая ошибка JavaScript: typeof null === \"object\". Для проверки на null используйте value === null.","en":"This is a historical bug in JavaScript: typeof null === \"object\". Use value === null to check for null."}'::jsonb, 10),
  ('js-02', 'javascript', 'easy', '{"uz":"Konsolga nima chiqadi?","ru":"Что будет выведено в консоль?","en":"What is logged to the console?"}'::jsonb, 'console.log(0 == ''0'', 0 === ''0'')', '[{"uz":"true false","ru":"true false","en":"true false"},{"uz":"false false","ru":"false false","en":"false false"},{"uz":"true true","ru":"true true","en":"true true"},{"uz":"false true","ru":"false true","en":"false true"}]'::jsonb, 0, '{"uz":"== tiplarni moslashtiradi (type coercion): \"0\" raqamga aylanadi. === esa tip va qiymatni o‘zgartirmasdan solishtiradi.","ru":"== выполняет приведение типов: \"0\" превращается в число. === сравнивает без приведения — и тип, и значение.","en":"== performs type coercion: \"0\" is converted to a number. === compares type and value without coercion."}'::jsonb, 10),
  ('js-03', 'javascript', 'medium', '{"uz":"Konsolga nima chiqadi?","ru":"Что будет выведено в консоль?","en":"What is logged to the console?"}'::jsonb, 'console.log(a)
var a = 5', '[{"uz":"5","ru":"5","en":"5"},{"uz":"ReferenceError","ru":"ReferenceError","en":"ReferenceError"},{"uz":"undefined","ru":"undefined","en":"undefined"},{"uz":"null","ru":"null","en":"null"}]'::jsonb, 2, '{"uz":"var e’lonlari hoisting bo‘ladi va undefined bilan initsializatsiya qilinadi; qiymat (5) esa faqat o‘sha qatorda beriladi.","ru":"Объявления var поднимаются (hoisting) и инициализируются undefined; присваивание 5 происходит только на своей строке.","en":"var declarations are hoisted and initialized with undefined; the assignment of 5 only happens on its own line."}'::jsonb, 15),
  ('js-04', 'javascript', 'medium', '{"uz":"Bu kod bajarilganda nima bo‘ladi?","ru":"Что произойдёт при выполнении кода?","en":"What happens when this code runs?"}'::jsonb, 'console.log(b)
let b = 1', '[{"uz":"undefined chiqadi","ru":"Выведется undefined","en":"undefined is logged"},{"uz":"1 chiqadi","ru":"Выведется 1","en":"1 is logged"},{"uz":"null chiqadi","ru":"Выведется null","en":"null is logged"},{"uz":"ReferenceError — b “temporal dead zone”da","ru":"ReferenceError — b находится во «временной мёртвой зоне»","en":"ReferenceError — b is in the temporal dead zone"}]'::jsonb, 3, '{"uz":"let va const ham hoisting bo‘ladi, lekin e’lon qatorigacha initsializatsiya qilinmaydi (TDZ). Ularga oldindan murojaat ReferenceError beradi.","ru":"let и const тоже поднимаются, но не инициализируются до строки объявления (TDZ). Обращение к ним раньше вызывает ReferenceError.","en":"let and const are hoisted too but not initialized until their declaration (TDZ). Accessing them earlier throws a ReferenceError."}'::jsonb, 15),
  ('js-05', 'javascript', 'medium', '{"uz":"Closure (yopilish) nima?","ru":"Что такое замыкание (closure)?","en":"What is a closure?"}'::jsonb, 'function counter() {
  let n = 0
  return () => ++n
}
const inc = counter()
inc(); inc() // 2', '[{"uz":"Funksiyani darhol chaqirish usuli","ru":"Способ немедленно вызвать функцию","en":"A way to call a function immediately"},{"uz":"Funksiyaning o‘zi yaratilgan leksik muhitdagi o‘zgaruvchilarga, tashqi funksiya tugaganidan keyin ham kira olishi","ru":"Способность функции обращаться к переменным лексического окружения, где она создана, даже после завершения внешней функции","en":"A function''s ability to access variables from the lexical scope where it was created, even after the outer function has returned"},{"uz":"Obyektni muzlatish usuli","ru":"Способ заморозить объект","en":"A way to freeze an object"},{"uz":"Brauzer oynasini yopish hodisasi","ru":"Событие закрытия окна браузера","en":"The browser window close event"}]'::jsonb, 1, '{"uz":"Misolda qaytarilgan arrow funksiya n o‘zgaruvchisini “eslab qoladi”. Closure’lar xususiy holat, fabrikalar, debounce va React hook’larida keng ishlatiladi.","ru":"В примере возвращаемая стрелочная функция «помнит» переменную n. Замыкания используются для приватного состояния, фабрик, debounce и в хуках React.","en":"In the example the returned arrow function \"remembers\" n. Closures power private state, factories, debounce and React hooks."}'::jsonb, 15),
  ('js-06', 'javascript', 'hard', '{"uz":"Konsolga qanday tartibda chiqadi?","ru":"В каком порядке будет вывод в консоль?","en":"In what order are the values logged?"}'::jsonb, 'console.log(1)
setTimeout(() => console.log(2), 0)
Promise.resolve().then(() => console.log(3))
console.log(4)', '[{"uz":"1 2 3 4","ru":"1 2 3 4","en":"1 2 3 4"},{"uz":"1 4 2 3","ru":"1 4 2 3","en":"1 4 2 3"},{"uz":"1 4 3 2","ru":"1 4 3 2","en":"1 4 3 2"},{"uz":"1 3 4 2","ru":"1 3 4 2","en":"1 3 4 2"}]'::jsonb, 2, '{"uz":"Avval sinxron kod (1, 4), keyin microtask navbati (Promise → 3), so‘ng macrotask (setTimeout → 2). Microtask’lar har doim keyingi macrotask’dan oldin bajariladi.","ru":"Сначала синхронный код (1, 4), затем очередь микрозадач (Promise → 3), потом макрозадача (setTimeout → 2). Микрозадачи всегда выполняются до следующей макрозадачи.","en":"Synchronous code first (1, 4), then the microtask queue (Promise → 3), then the macrotask (setTimeout → 2). Microtasks always run before the next macrotask."}'::jsonb, 20),
  ('js-07', 'javascript', 'easy', '{"uz":"Massivning har bir elementini o‘zgartirib, yangi massiv qaytaradigan metod qaysi?","ru":"Какой метод возвращает новый массив, преобразовав каждый элемент?","en":"Which method returns a new array with every element transformed?"}'::jsonb, null, '[{"uz":"map()","ru":"map()","en":"map()"},{"uz":"forEach()","ru":"forEach()","en":"forEach()"},{"uz":"filter()","ru":"filter()","en":"filter()"},{"uz":"find()","ru":"find()","en":"find()"}]'::jsonb, 0, '{"uz":"map() har bir element uchun callback natijasidan iborat yangi massiv qaytaradi. forEach() hech narsa qaytarmaydi (undefined), filter() elementlarni tanlaydi.","ru":"map() возвращает новый массив из результатов callback для каждого элемента. forEach() ничего не возвращает (undefined), filter() отбирает элементы.","en":"map() returns a new array of callback results. forEach() returns undefined, and filter() selects elements."}'::jsonb, 10),
  ('js-08', 'javascript', 'easy', '{"uz":"Natija nima?","ru":"Каков результат?","en":"What is the result?"}'::jsonb, '[1, 2, 3].reduce((acc, n) => acc + n, 0)', '[{"uz":"\"123\"","ru":"\"123\"","en":"\"123\""},{"uz":"[1, 2, 3]","ru":"[1, 2, 3]","en":"[1, 2, 3]"},{"uz":"0","ru":"0","en":"0"},{"uz":"6","ru":"6","en":"6"}]'::jsonb, 3, '{"uz":"reduce akkumulyatorni 0 dan boshlaydi va har bir elementni qo‘shadi: 0+1+2+3 = 6.","ru":"reduce начинает аккумулятор с 0 и прибавляет каждый элемент: 0+1+2+3 = 6.","en":"reduce starts the accumulator at 0 and adds each element: 0+1+2+3 = 6."}'::jsonb, 10),
  ('js-09', 'javascript', 'medium', '{"uz":"Konsolga nima chiqadi?","ru":"Что будет выведено?","en":"What is logged?"}'::jsonb, 'const user = {
  name: ''Ali'',
