console.log(user.regular(), user.arrow())', '[{"uz":"''Ali'' ''Ali''","ru":"''Ali'' ''Ali''","en":"''Ali'' ''Ali''"},{"uz":"''Ali'' undefined","ru":"''Ali'' undefined","en":"''Ali'' undefined"},{"uz":"undefined ''Ali''","ru":"undefined ''Ali''","en":"undefined ''Ali''"},{"uz":"TypeError","ru":"TypeError","en":"TypeError"}]'::jsonb, 1, '{"uz":"Arrow funksiyalarning o‘z this’i yo‘q — u tashqi leksik muhitdan olinadi (modulda undefined). Oddiy metodda this chaqiruvchi obyektga (user) teng.","ru":"У стрелочных функций нет своего this — он берётся из внешнего лексического окружения (в модуле это undefined). В обычном методе this — объект вызова (user).","en":"Arrow functions have no own this — it is taken from the enclosing lexical scope (undefined in a module). In a regular method this is the calling object (user)."}'::jsonb, 15),
  ('js-10', 'javascript', 'hard', '{"uz":"Konsolga nima chiqadi?","ru":"Что будет выведено?","en":"What is logged?"}'::jsonb, 'for (var i = 0; i < 3; i++) {
  setTimeout(() => console.log(i), 0)
}', '[{"uz":"0 1 2","ru":"0 1 2","en":"0 1 2"},{"uz":"undefined ×3","ru":"undefined ×3","en":"undefined ×3"},{"uz":"3 3 3","ru":"3 3 3","en":"3 3 3"},{"uz":"2 2 2","ru":"2 2 2","en":"2 2 2"}]'::jsonb, 2, '{"uz":"var funksiya darajasida bitta o‘zgaruvchi yaratadi; callback’lar ishga tushganda sikl tugagan va i = 3. let ishlatilsa, har iteratsiya uchun alohida binding bo‘lib, 0 1 2 chiqadi.","ru":"var создаёт одну переменную на функцию; когда колбэки срабатывают, цикл уже завершён и i = 3. С let каждая итерация получает свою привязку, и выведется 0 1 2.","en":"var creates a single function-scoped variable; when the callbacks run, the loop has finished and i = 3. With let, each iteration gets its own binding and 0 1 2 is logged."}'::jsonb, 20),
  ('js-11', 'javascript', 'medium', '{"uz":"a.inner.x ning qiymati nima bo‘ladi?","ru":"Чему будет равно a.inner.x?","en":"What will a.inner.x be?"}'::jsonb, 'const a = { inner: { x: 1 } }
const b = { ...a }
b.inner.x = 2', '[{"uz":"2","ru":"2","en":"2"},{"uz":"1","ru":"1","en":"1"},{"uz":"undefined","ru":"undefined","en":"undefined"},{"uz":"TypeError","ru":"TypeError","en":"TypeError"}]'::jsonb, 0, '{"uz":"Spread operator sayoz (shallow) nusxa yaratadi: b.inner va a.inner bitta obyektga ishora qiladi. Chuqur nusxa uchun structuredClone() ishlating.","ru":"Spread создаёт поверхностную копию: b.inner и a.inner ссылаются на один объект. Для глубокой копии используйте structuredClone().","en":"Spread makes a shallow copy: b.inner and a.inner point to the same object. Use structuredClone() for a deep copy."}'::jsonb, 15),
  ('js-12', 'javascript', 'easy', '{"uz":"Qiymat massiv ekanligini tekshirishning ishonchli usuli qaysi?","ru":"Какой надёжный способ проверить, что значение — массив?","en":"What is the reliable way to check that a value is an array?"}'::jsonb, null, '[{"uz":"typeof value === ''array''","ru":"typeof value === ''array''","en":"typeof value === ''array''"},{"uz":"value instanceof Object","ru":"value instanceof Object","en":"value instanceof Object"},{"uz":"value.length !== undefined","ru":"value.length !== undefined","en":"value.length !== undefined"},{"uz":"Array.isArray(value)","ru":"Array.isArray(value)","en":"Array.isArray(value)"}]'::jsonb, 3, '{"uz":"typeof [] — \"object\", length esa satrlarda ham bor. Array.isArray() turli iframe/realm’lardagi massivlar uchun ham to‘g‘ri ishlaydi.","ru":"typeof [] — \"object\", а length есть и у строк. Array.isArray() корректно работает даже для массивов из других iframe/realm.","en":"typeof [] is \"object\" and strings also have length. Array.isArray() works correctly even for arrays from other iframes/realms."}'::jsonb, 10),
  ('js-13', 'javascript', 'medium', '{"uz":"Qaysi metod barcha promise’lar yakunlanishini kutadi va ulardan biri reject bo‘lsa ham to‘xtamaydi?","ru":"Какой метод ждёт завершения всех промисов и не прерывается, если один из них отклонён?","en":"Which method waits for all promises to settle and does not short-circuit when one rejects?"}'::jsonb, null, '[{"uz":"Promise.all()","ru":"Promise.all()","en":"Promise.all()"},{"uz":"Promise.allSettled()","ru":"Promise.allSettled()","en":"Promise.allSettled()"},{"uz":"Promise.race()","ru":"Promise.race()","en":"Promise.race()"},{"uz":"Promise.any()","ru":"Promise.any()","en":"Promise.any()"}]'::jsonb, 1, '{"uz":"allSettled har bir promise uchun {status, value | reason} qaytaradi. all birinchi reject’dayoq reject bo‘ladi; race birinchi yakunlanganni, any birinchi muvaffaqiyatlisini qaytaradi.","ru":"allSettled возвращает {status, value | reason} для каждого промиса. all отклоняется при первом reject; race — первый завершённый, any — первый успешный.","en":"allSettled resolves with {status, value | reason} for each promise. all rejects on the first rejection; race settles with the first settled, any with the first fulfilled."}'::jsonb, 15),
  ('js-14', 'javascript', 'medium', '{"uz":"a va b qiymatlari qanday?","ru":"Каковы значения a и b?","en":"What are the values of a and b?"}'::jsonb, 'const { a = 10, b = 20 } = { a: undefined, b: null }', '[{"uz":"a = 10, b = 20","ru":"a = 10, b = 20","en":"a = 10, b = 20"},{"uz":"a = undefined, b = null","ru":"a = undefined, b = null","en":"a = undefined, b = null"},{"uz":"a = 10, b = null","ru":"a = 10, b = null","en":"a = 10, b = null"},{"uz":"a = undefined, b = 20","ru":"a = undefined, b = 20","en":"a = undefined, b = 20"}]'::jsonb, 2, '{"uz":"Destructuring’dagi default qiymat faqat qiymat aynan undefined bo‘lganda qo‘llanadi. null — haqiqiy qiymat, shuning uchun b = null.","ru":"Значение по умолчанию при деструктуризации применяется только если значение строго undefined. null — это значение, поэтому b = null.","en":"Destructuring defaults only apply when the value is strictly undefined. null is a real value, so b = null."}'::jsonb, 15),
  ('js-15', 'javascript', 'medium', '{"uz":"Natija nima?","ru":"Каков результат?","en":"What is the result?"}'::jsonb, '0.1 + 0.2 === 0.3', '[{"uz":"false — IEEE 754 suzuvchi nuqta xatoligi tufayli","ru":"false — из‑за погрешности чисел с плавающей точкой IEEE 754","en":"false — due to IEEE 754 floating-point precision"},{"uz":"true","ru":"true","en":"true"},{"uz":"TypeError","ru":"TypeError","en":"TypeError"},{"uz":"NaN","ru":"NaN","en":"NaN"}]'::jsonb, 0, '{"uz":"0.1 + 0.2 = 0.30000000000000004. Kasr sonlarni solishtirishda Math.abs(a - b) < Number.EPSILON dan foydalaning yoki butun sonlarda (tiyinlarda) hisoblang.","ru":"0.1 + 0.2 = 0.30000000000000004. Для сравнения дробных используйте Math.abs(a - b) < Number.EPSILON или считайте в целых (копейках).","en":"0.1 + 0.2 = 0.30000000000000004. Compare floats with Math.abs(a - b) < Number.EPSILON or work in integers (cents)."}'::jsonb, 15),
  ('js-16', 'javascript', 'medium', '{"uz":"Event delegation nima?","ru":"Что такое делегирование событий?","en":"What is event delegation?"}'::jsonb, 'list.addEventListener(''click'', (e) => {
  const item = e.target.closest(''li'')
  if (item) select(item.dataset.id)
})', '[{"uz":"Hodisani boshqa funksiyaga nusxalash","ru":"Копирование события в другую функцию","en":"Copying an event to another function"},{"uz":"Hodisani to‘xtatish uchun preventDefault chaqirish","ru":"Вызов preventDefault для остановки события","en":"Calling preventDefault to stop the event"},{"uz":"Har bir elementga alohida listener qo‘shish","ru":"Добавление отдельного обработчика на каждый элемент","en":"Adding a separate listener to every element"},{"uz":"Bubbling’dan foydalanib, ko‘plab bolalar hodisalarini ota elementdagi bitta listener orqali boshqarish","ru":"Обработка событий многих потомков одним обработчиком на родителе благодаря всплытию","en":"Handling events of many children with one listener on a parent, using bubbling"}]'::jsonb, 3, '{"uz":"Delegation xotirani tejaydi va dinamik qo‘shilgan elementlar uchun ham avtomatik ishlaydi. e.target.closest() bilan kerakli elementni topamiz.","ru":"Делегирование экономит память и автоматически работает для динамически добавленных элементов. e.target.closest() находит нужный элемент.","en":"Delegation saves memory and automatically works for dynamically added elements. e.target.closest() finds the relevant element."}'::jsonb, 15),
  ('js-17', 'javascript', 'medium', '{"uz":"Debounce funksiyasi nima qiladi?","ru":"Что делает функция debounce?","en":"What does a debounce function do?"}'::jsonb, null, '[{"uz":"Funksiyani har N ms da bir martadan ko‘p chaqirmaydi","ru":"Вызывает функцию не чаще раза в N мс","en":"Calls the function at most once every N ms"},{"uz":"Chaqiruvlar to‘xtaganidan N ms o‘tgandan keyingina funksiyani bir marta chaqiradi","ru":"Вызывает функцию один раз только спустя N мс после прекращения вызовов","en":"Calls the function once, only after calls have stopped for N ms"},{"uz":"Funksiya natijasini keshlaydi","ru":"Кэширует результат функции","en":"Caches the function result"},{"uz":"Funksiyani parallel oqimda bajaradi","ru":"Выполняет функцию в параллельном потоке","en":"Runs the function in a parallel thread"}]'::jsonb, 1, '{"uz":"Debounce qidiruv maydoni, resize kabi tez-tez hodisalar uchun ishlatiladi. Birinchi variant — throttle tavsifi, uchinchisi — memoization.","ru":"Debounce используют для поиска, resize и других частых событий. Первый вариант описывает throttle, третий — мемоизацию.","en":"Debounce is used for search inputs, resize and other noisy events. The first option describes throttle and the third describes memoization."}'::jsonb, 15),
  ('js-18', 'javascript', 'hard', '{"uz":"Konsolga nima chiqadi?","ru":"Что будет выведено?","en":"What is logged?"}'::jsonb, 'async function load() {
  try {
    await Promise.reject(new Error(''x''))
    return ''ok''
  } catch {
    return ''caught''
  } finally {
    console.log(''done'')
  }
}
load().then(console.log)', '[{"uz":"''ok'' ''done''","ru":"''ok'' ''done''","en":"''ok'' ''done''"},{"uz":"Unhandled rejection: x","ru":"Unhandled rejection: x","en":"Unhandled rejection: x"},{"uz":"''done'' ''caught''","ru":"''done'' ''caught''","en":"''done'' ''caught''"},{"uz":"''caught'' ''done''","ru":"''caught'' ''done''","en":"''caught'' ''done''"}]'::jsonb, 2, '{"uz":"Rejected promise’ni await qilish catch blokiga tushiradi. finally return’dan oldin bajariladi, shuning uchun avval \"done\", keyin then() orqali \"caught\" chiqadi.","ru":"await отклонённого промиса бросает исключение в catch. finally выполняется до фактического возврата, поэтому сначала \"done\", затем через then() — \"caught\".","en":"Awaiting a rejected promise throws into catch. finally runs before the function actually returns, so \"done\" is logged first, then \"caught\" via then()."}'::jsonb, 20),
  ('js-19', 'javascript', 'easy', '{"uz":"Bu kod ishlaydimi?","ru":"Сработает ли этот код?","en":"Does this code work?"}'::jsonb, 'const user = { name: ''Ali'' }
user.name = ''Vali''
console.log(user.name)', '[{"uz":"Ha — ''Vali'' chiqadi: const faqat qayta tayinlashni taqiqlaydi, obyekt o‘zgarishini emas","ru":"Да — выведется ''Vali'': const запрещает переприсваивание, а не изменение объекта","en":"Yes — logs ''Vali'': const prevents reassignment, not mutation of the object"},{"uz":"TypeError: const obyektni o‘zgartirib bo‘lmaydi","ru":"TypeError: const-объект нельзя менять","en":"TypeError: a const object cannot be changed"},{"uz":"''Ali'' chiqadi","ru":"Выведется ''Ali''","en":"Logs ''Ali''"},{"uz":"SyntaxError","ru":"SyntaxError","en":"SyntaxError"}]'::jsonb, 0, '{"uz":"const o‘zgaruvchi boshqa qiymatga ishora qila olmaydi (user = {} — xato), lekin obyekt ichini o‘zgartirish mumkin. To‘liq muzlatish uchun Object.freeze().","ru":"const-переменную нельзя переназначить (user = {} — ошибка), но содержимое объекта менять можно. Для заморозки — Object.freeze().","en":"A const binding cannot point to a new value (user = {} throws), but the object''s contents can change. Use Object.freeze() to prevent that."}'::jsonb, 10),
  ('js-20', 'javascript', 'hard', '{"uz":"Qaysi usul Date obyektlarini saqlagan holda chuqur nusxa (deep copy) yaratadi?","ru":"Какой способ создаёт глубокую копию, сохраняя объекты Date?","en":"Which approach creates a deep copy while preserving Date objects?"}'::jsonb, 'const original = { created: new Date(), tags: [''a''] }', '[{"uz":"JSON.parse(JSON.stringify(original))","ru":"JSON.parse(JSON.stringify(original))","en":"JSON.parse(JSON.stringify(original))"},{"uz":"Object.assign({}, original)","ru":"Object.assign({}, original)","en":"Object.assign({}, original)"},{"uz":"{ ...original }","ru":"{ ...original }","en":"{ ...original }"},{"uz":"structuredClone(original)","ru":"structuredClone(original)","en":"structuredClone(original)"}]'::jsonb, 3, '{"uz":"structuredClone Date, Map, Set va siklik havolalarni to‘g‘ri nusxalaydi. JSON usuli Date’ni satrga aylantiradi, spread va Object.assign esa sayoz nusxa beradi.","ru":"structuredClone корректно копирует Date, Map, Set и циклические ссылки. JSON превращает Date в строку, а spread и Object.assign делают поверхностную копию.","en":"structuredClone correctly copies Date, Map, Set and circular references. JSON turns Date into a string; spread and Object.assign are shallow."}'::jsonb, 20),
  ('react-01', 'react', 'easy', '{"uz":"JSX nima?","ru":"Что такое JSX?","en":"What is JSX?"}'::jsonb, null, '[{"uz":"Brauzer to‘g‘ridan-to‘g‘ri bajaradigan yangi dasturlash tili","ru":"Новый язык, который браузер выполняет напрямую","en":"A new language browsers execute directly"},{"uz":"JavaScript sintaksis kengaytmasi, u jsx()/React.createElement chaqiruvlariga kompilyatsiya qilinadi","ru":"Расширение синтаксиса JavaScript, которое компилируется в вызовы jsx()/React.createElement","en":"A JavaScript syntax extension compiled into jsx()/React.createElement calls"},{"uz":"HTML shablonlash dvigateli, server tomonda ishlaydi","ru":"HTML-шаблонизатор, работающий на сервере","en":"A server-side HTML template engine"},{"uz":"CSS-in-JS kutubxonasi","ru":"Библиотека CSS-in-JS","en":"A CSS-in-JS library"}]'::jsonb, 1, '{"uz":"Brauzer JSX’ni tushunmaydi — Babel/SWC/esbuild uni oddiy JS funksiya chaqiruvlariga aylantiradi. Shu sababli JSX ichida {} orqali JS ifodalarini yozish mumkin.","ru":"Браузер не понимает JSX — Babel/SWC/esbuild превращают его в обычные вызовы функций JS. Поэтому внутри JSX можно писать JS-выражения в {}.","en":"Browsers do not understand JSX — Babel/SWC/esbuild turn it into plain JS function calls. That is why you can embed JS expressions in {}."}'::jsonb, 10),
  ('react-02', 'react', 'easy', '{"uz":"Bola komponent o‘ziga kelgan props’ni o‘zgartira oladimi?","ru":"Может ли дочерний компонент изменять полученные props?","en":"Can a child component modify the props it receives?"}'::jsonb, null, '[{"uz":"Yo‘q — props faqat o‘qish uchun; o‘zgartirish uchun ota callback uzatadi","ru":"Нет — props только для чтения; для изменений родитель передаёт колбэк","en":"No — props are read-only; the parent passes a callback to request changes"},{"uz":"Ha, props.value = x deb yozish kifoya","ru":"Да, достаточно написать props.value = x","en":"Yes, just write props.value = x"},{"uz":"Faqat class komponentlarda","ru":"Только в классовых компонентах","en":"Only in class components"},{"uz":"Faqat useEffect ichida","ru":"Только внутри useEffect","en":"Only inside useEffect"}]'::jsonb, 0, '{"uz":"Ma’lumot yuqoridan pastga oqadi (one-way data flow). Bola holatni o‘zgartirish uchun ota tomonidan uzatilgan onChange kabi funksiyani chaqiradi.","ru":"Данные текут сверху вниз (one-way data flow). Чтобы изменить состояние, ребёнок вызывает функцию, переданную родителем, например onChange.","en":"Data flows down (one-way data flow). To change state, the child calls a function passed by the parent, such as onChange."}'::jsonb, 10),
  ('react-03', 'react', 'easy', '{"uz":"useState nimani qaytaradi?","ru":"Что возвращает useState?","en":"What does useState return?"}'::jsonb, 'const result = useState(0)', '[{"uz":"Faqat joriy qiymatni","ru":"Только текущее значение","en":"Only the current value"},{"uz":"Promise’ni","ru":"Promise","en":"A Promise"},{"uz":"Ikki elementli massiv: [joriy qiymat, uni yangilovchi funksiya]","ru":"Массив из двух элементов: [текущее значение, функция обновления]","en":"A two-element array: [current value, setter function]"},{"uz":"{ state, setState } obyektini","ru":"Объект { state, setState }","en":"An object { state, setState }"}]'::jsonb, 2, '{"uz":"Odatda destructuring bilan yoziladi: const [count, setCount] = useState(0). Setter chaqirilganda komponent qayta render qilinadi.","ru":"Обычно пишут с деструктуризацией: const [count, setCount] = useState(0). Вызов сеттера приводит к повторному рендеру.","en":"It is usually destructured: const [count, setCount] = useState(0). Calling the setter schedules a re-render."}'::jsonb, 10),
  ('react-04', 'react', 'medium', '{"uz":"Ro‘yxat render qilinganda key prop nima uchun kerak?","ru":"Зачем нужен prop key при рендере списков?","en":"Why is the key prop needed when rendering lists?"}'::jsonb, '{todos.map(todo => <TodoItem key={todo.id} todo={todo} />)}', '[{"uz":"Elementlarni alifbo tartibida saralash uchun","ru":"Для сортировки элементов по алфавиту","en":"To sort items alphabetically"},{"uz":"CSS stillarini qo‘llash uchun","ru":"Для применения CSS-стилей","en":"To apply CSS styles"},{"uz":"Komponentga id prop sifatida yetkazish uchun","ru":"Чтобы передать компоненту id как prop","en":"To pass the id as a prop to the component"},{"uz":"React renderlar orasida qaysi element qaysi ekanini aniqlashi va holatni to‘g‘ri saqlashi uchun","ru":"Чтобы React понимал, какой элемент какой между рендерами, и корректно сохранял состояние","en":"So React can identify which item is which between renders and preserve state correctly"}]'::jsonb, 3, '{"uz":"key reconciliation jarayonida ishlatiladi va komponentga props sifatida yetib bormaydi. U barqaror va aka-ukalar orasida unikal bo‘lishi kerak.","ru":"key используется при согласовании (reconciliation) и не передаётся в компонент как prop. Он должен быть стабильным и уникальным среди соседей.","en":"key is used during reconciliation and is not passed to the component as a prop. It must be stable and unique among siblings."}'::jsonb, 15),
  ('react-05', 'react', 'medium', '{"uz":"key sifatida massiv indeksidan foydalanish qachon xatoga olib keladi?","ru":"Когда использование индекса массива в качестве key приводит к ошибкам?","en":"When does using the array index as a key cause bugs?"}'::jsonb, null, '[{"uz":"Hech qachon — bu tavsiya etilgan usul","ru":"Никогда — это рекомендуемый способ","en":"Never — it is the recommended approach"},{"uz":"Elementlar qo‘shilsa, o‘chirilsa yoki tartibi o‘zgarsa — holat (masalan, input qiymati) noto‘g‘ri elementga “o‘tib” qoladi","ru":"Когда элементы добавляются, удаляются или меняют порядок — состояние (например, значение input) «переезжает» к другому элементу","en":"When items are inserted, removed or reordered — state (e.g. input values) sticks to the wrong item"},{"uz":"Faqat ro‘yxatda 100 dan ortiq element bo‘lsa","ru":"Только если в списке больше 100 элементов","en":"Only when the list has more than 100 items"},{"uz":"Faqat class komponentlarda","ru":"Только в классовых компонентах","en":"Only in class components"}]'::jsonb, 1, '{"uz":"Indeks elementga emas, pozitsiyaga bog‘langan. Statik, o‘zgarmaydigan ro‘yxatlarda indeks qabul qilinadi, boshqa hollarda barqaror id ishlating.","ru":"Индекс привязан к позиции, а не к элементу. Для статичных неизменяемых списков индекс допустим, в остальных случаях используйте стабильный id.","en":"An index identifies a position, not an item. It is acceptable for static lists that never change; otherwise use a stable id."}'::jsonb, 15),
  ('react-06', 'react', 'medium', '{"uz":"Bo‘sh bog‘liqliklar massivi bilan useEffect qachon ishlaydi?","ru":"Когда выполняется useEffect с пустым массивом зависимостей?","en":"When does useEffect with an empty dependency array run?"}'::jsonb, 'useEffect(() => {
  const id = connect()
  return () => disconnect(id)
}, [])', '[{"uz":"Har bir renderdan keyin","ru":"После каждого рендера","en":"After every render"},{"uz":"Renderdan oldin, sinxron","ru":"Перед рендером, синхронно","en":"Before render, synchronously"},{"uz":"Mount’dan keyin bir marta, cleanup esa unmount’da (dev StrictMode’da qo‘shimcha mount/unmount sikli bo‘ladi)","ru":"Один раз после монтирования, cleanup — при размонтировании (в dev StrictMode есть дополнительный цикл mount/unmount)","en":"Once after mount, with cleanup on unmount (dev StrictMode adds an extra mount/unmount cycle)"},{"uz":"Hech qachon","ru":"Никогда","en":"Never"}]'::jsonb, 2, '{"uz":"Bog‘liqliklar o‘zgarmagani uchun effekt qayta ishga tushmaydi. StrictMode dev rejimida cleanup to‘g‘ri yozilganini tekshirish uchun effektni ikki marta ishga tushiradi.","ru":"Зависимости не меняются, поэтому эффект не перезапускается. В dev-режиме StrictMode запускает эффект дважды, чтобы проверить корректность cleanup.","en":"Since dependencies never change, the effect never re-runs. In development StrictMode runs it twice to verify that cleanup is correct."}'::jsonb, 15),
  ('react-07', 'react', 'medium', '{"uz":"Tugma bir marta bosilgandan keyin count qiymati qancha bo‘ladi?","ru":"Чему будет равен count после одного клика?","en":"What will count be after one click?"}'::jsonb, 'const [count, setCount] = useState(0)

function handleClick() {
  setCount(count + 1)
  setCount(count + 1)
  setCount(count + 1)
}', '[{"uz":"1","ru":"1","en":"1"},{"uz":"3","ru":"3","en":"3"},{"uz":"0","ru":"0","en":"0"},{"uz":"2","ru":"2","en":"2"}]'::jsonb, 0, '{"uz":"Har uch chaqiruv ham shu renderdagi count = 0 ni ko‘radi, natija 0 + 1. Oldingi qiymatga tayanish uchun updater ishlating: setCount(c => c + 1).","ru":"Все три вызова видят count = 0 из текущего рендера, результат 0 + 1. Чтобы опираться на предыдущее значение, используйте updater: setCount(c => c + 1).","en":"All three calls see count = 0 from the current render, so the result is 0 + 1. Use an updater to build on the previous value: setCount(c => c + 1)."}'::jsonb, 15),
  ('react-08', 'react', 'hard', '{"uz":"Nega bu taymer count’ni faqat 1 gacha oshiradi?","ru":"Почему этот таймер увеличивает count только до 1?","en":"Why does this timer only ever increase count to 1?"}'::jsonb, 'useEffect(() => {
  const id = setInterval(() => {
    setCount(count + 1)
  }, 1000)
  return () => clearInterval(id)
}, [])', '[{"uz":"setInterval React ichida ishlamaydi","ru":"setInterval не работает внутри React","en":"setInterval does not work inside React"},{"uz":"clearInterval darhol chaqiriladi","ru":"clearInterval вызывается сразу","en":"clearInterval is called immediately"},{"uz":"React bir xil qiymatlarni birlashtirib yuboradi","ru":"React объединяет одинаковые значения","en":"React merges identical values"},{"uz":"Callback birinchi renderdagi count = 0 ni “eslab qolgan” (stale closure); setCount(c => c + 1) bilan tuzatiladi","ru":"Колбэк «запомнил» count = 0 из первого рендера (устаревшее замыкание); исправляется через setCount(c => c + 1)","en":"The callback captured count = 0 from the first render (stale closure); fix it with setCount(c => c + 1)"}]'::jsonb, 3, '{"uz":"Effekt faqat bir marta yaratilgan, shuning uchun ichidagi count doim 0. Updater funksiya yoki useRef eng yangi qiymatni olishga yordam beradi.","ru":"Эффект создан один раз, поэтому count внутри всегда 0. Функция-updater или useRef позволяют получить актуальное значение.","en":"The effect is created once, so count inside it is always 0. An updater function or a ref gives access to the latest value."}'::jsonb, 20),
  ('react-09', 'react', 'medium', '{"uz":"useMemo nima uchun ishlatiladi?","ru":"Для чего используется useMemo?","en":"What is useMemo used for?"}'::jsonb, 'const sorted = useMemo(() => sortBy(items, key), [items, key])', '[{"uz":"Komponentni xotiradan o‘chirish uchun","ru":"Для удаления компонента из памяти","en":"To remove a component from memory"},{"uz":"Qimmat hisoblash natijasini bog‘liqliklar o‘zgarmaguncha keshlash uchun","ru":"Для кэширования результата дорогого вычисления, пока зависимости не изменились","en":"To cache the result of an expensive computation until dependencies change"},{"uz":"Ma’lumotlarni serverdan yuklash uchun","ru":"Для загрузки данных с сервера","en":"To fetch data from the server"},{"uz":"Holatni localStorage’da saqlash uchun","ru":"Для сохранения состояния в localStorage","en":"To persist state in localStorage"}]'::jsonb, 1, '{"uz":"useMemo qiymatni memoizatsiya qiladi va barqaror havolalarni saqlashga yordam beradi. Har bir oddiy hisoblashga qo‘llash shart emas — u ham o‘z narxiga ega.","ru":"useMemo мемоизирует значение и помогает сохранять стабильные ссылки. Не нужно оборачивать в него каждое простое вычисление — это тоже имеет цену.","en":"useMemo memoizes a value and helps keep references stable. Do not wrap every trivial calculation — memoization has a cost too."}'::jsonb, 15),
  ('react-10', 'react', 'medium', '{"uz":"useCallback nima qaytaradi?","ru":"Что возвращает useCallback?","en":"What does useCallback return?"}'::jsonb, null, '[{"uz":"Funksiya chaqiruvi natijasini","ru":"Результат вызова функции","en":"The result of calling the function"},{"uz":"Promise’ni","ru":"Promise","en":"A Promise"},{"uz":"Bog‘liqliklar o‘zgarmaguncha bir xil havolaga ega memoizatsiya qilingan funksiyani","ru":"Мемоизированную функцию с той же ссылкой, пока зависимости не изменились","en":"A memoized function that keeps the same reference until dependencies change"},{"uz":"Yangi komponentni","ru":"Новый компонент","en":"A new component"}]'::jsonb, 2, '{"uz":"useCallback(fn, deps) ≈ useMemo(() => fn, deps). React.memo bilan o‘ralgan bolaga callback uzatilganda keraksiz renderlarning oldini oladi.","ru":"useCallback(fn, deps) ≈ useMemo(() => fn, deps). Полезен при передаче колбэков в дочерние компоненты, обёрнутые в React.memo.","en":"useCallback(fn, deps) ≈ useMemo(() => fn, deps). Useful when passing callbacks to children wrapped in React.memo."}'::jsonb, 15),
  ('react-11', 'react', 'medium', '{"uz":"React.memo nima qiladi?","ru":"Что делает React.memo?","en":"What does React.memo do?"}'::jsonb, 'const Row = React.memo(function Row({ user }) {
  return <li>{user.name}</li>
})', '[{"uz":"Props sayoz (shallow) teng bo‘lsa, komponentni qayta render qilmaydi","ru":"Пропускает повторный рендер, если props поверхностно равны","en":"Skips re-rendering when props are shallowly equal"},{"uz":"Komponent holatini saqlaydi","ru":"Сохраняет состояние компонента","en":"Persists the component''s state"},{"uz":"Komponentni lazy yuklaydi","ru":"Лениво загружает компонент","en":"Lazy-loads the component"},{"uz":"Xatolarni ushlaydi","ru":"Перехватывает ошибки","en":"Catches errors"}]'::jsonb, 0, '{"uz":"memo props’ni Object.is bilan solishtiradi. Har renderda yangi obyekt yoki funksiya uzatilsa, memo foyda bermaydi — useMemo/useCallback kerak bo‘ladi.","ru":"memo сравнивает props через Object.is. Если на каждом рендере передаются новые объекты или функции, memo бесполезен — нужны useMemo/useCallback.","en":"memo compares props with Object.is. If you pass new objects or functions every render, memo will not help — you need useMemo/useCallback."}'::jsonb, 15),
  ('react-12', 'react', 'easy', '{"uz":"Controlled component nima?","ru":"Что такое контролируемый компонент?","en":"What is a controlled component?"}'::jsonb, '<input value={name} onChange={e => setName(e.target.value)} />', '[{"uz":"Admin tomonidan boshqariladigan komponent","ru":"Компонент, которым управляет администратор","en":"A component managed by an admin"},{"uz":"Qiymatini DOM o‘zi saqlaydigan input","ru":"Input, значение которого хранит сам DOM","en":"An input whose value is stored by the DOM itself"},{"uz":"Faqat o‘qish uchun bo‘lgan komponent","ru":"Компонент только для чтения","en":"A read-only component"},{"uz":"Qiymati React holati orqali boshqariladigan va onChange orqali yangilanadigan forma elementi","ru":"Элемент формы, значение которого управляется состоянием React и обновляется через onChange","en":"A form element whose value is driven by React state and updated via onChange"}]'::jsonb, 3, '{"uz":"Controlled’da “haqiqat manbai” — React state. Uncontrolled’da qiymat DOM’da bo‘ladi va ref orqali o‘qiladi (defaultValue).","ru":"В контролируемом компоненте «источник истины» — состояние React. В неконтролируемом значение живёт в DOM и читается через ref (defaultValue).","en":"In a controlled component React state is the source of truth. In an uncontrolled one the DOM holds the value and you read it via a ref (defaultValue)."}'::jsonb, 10),
  ('react-13', 'react', 'medium', '{"uz":"useRef haqida qaysi gap to‘g‘ri?","ru":"Какое утверждение о useRef верно?","en":"Which statement about useRef is true?"}'::jsonb, null, '[{"uz":"ref.current o‘zgarsa, komponent qayta render bo‘ladi","ru":"Изменение ref.current вызывает повторный рендер","en":"Changing ref.current triggers a re-render"},{"uz":"U renderlar orasida saqlanadigan o‘zgaruvchan obyekt qaytaradi; .current o‘zgarishi renderga sabab bo‘lmaydi","ru":"Возвращает изменяемый объект, живущий между рендерами; изменение .current не вызывает рендер","en":"It returns a mutable object that persists across renders; changing .current does not cause a render"},{"uz":"Faqat DOM elementlar uchun ishlaydi","ru":"Работает только с DOM-элементами","en":"It only works with DOM elements"},{"uz":"Har renderda yangi obyekt yaratadi","ru":"Создаёт новый объект на каждом рендере","en":"It creates a new object on every render"}]'::jsonb, 1, '{"uz":"useRef DOM elementga kirish uchun ham, taymer id, oldingi qiymat kabi renderga ta’sir qilmaydigan ma’lumotlarni saqlash uchun ham ishlatiladi.","ru":"useRef используют и для доступа к DOM, и для хранения данных, не влияющих на рендер: id таймера, предыдущее значение и т.п.","en":"useRef is used both for DOM access and for storing values that should not trigger renders: timer ids, previous values, etc."}'::jsonb, 15),
  ('react-14', 'react', 'hard', '{"uz":"userId 1 dan 2 ga o‘zgarganda konsolga qanday tartibda chiqadi?","ru":"В каком порядке будет вывод, когда userId меняется с 1 на 2?","en":"In what order are messages logged when userId changes from 1 to 2?"}'::jsonb, 'useEffect(() => {
  console.log(''subscribe'', userId)
  return () => console.log(''cleanup'', userId)
}, [userId])', '[{"uz":"subscribe 2 → cleanup 1","ru":"subscribe 2 → cleanup 1","en":"subscribe 2 → cleanup 1"},{"uz":"subscribe 2 → cleanup 2","ru":"subscribe 2 → cleanup 2","en":"subscribe 2 → cleanup 2"},{"uz":"cleanup 1 → subscribe 2","ru":"cleanup 1 → subscribe 2","en":"cleanup 1 → subscribe 2"},{"uz":"cleanup 2 → subscribe 2","ru":"cleanup 2 → subscribe 2","en":"cleanup 2 → subscribe 2"}]'::jsonb, 2, '{"uz":"Yangi effekt ishga tushishidan oldin oldingi effektning cleanup’i o‘zining eski qiymatlari (userId = 1) bilan bajariladi. Cleanup unmount paytida ham chaqiriladi.","ru":"Перед запуском нового эффекта выполняется cleanup предыдущего — со своими старыми значениями (userId = 1). Cleanup также вызывается при размонтировании.","en":"Before the new effect runs, the previous effect''s cleanup runs with its own old values (userId = 1). Cleanup also runs on unmount."}'::jsonb, 20),
  ('react-15', 'react', 'medium', '{"uz":"Ikki aka-uka komponent bitta holatdan foydalanishi kerak. Eng to‘g‘ri yechim qaysi?","ru":"Двум соседним компонентам нужно общее состояние. Какое решение самое правильное?","en":"Two sibling components need to share state. What is the most appropriate solution?"}'::jsonb, null, '[{"uz":"Holatni eng yaqin umumiy ota komponentga ko‘tarish (lifting state up) va props orqali uzatish","ru":"Поднять состояние в ближайшего общего родителя (lifting state up) и передать через props","en":"Lift the state up to the closest common parent and pass it down via props"},{"uz":"Har bir komponentda holatni nusxalab, useEffect bilan sinxronlash","ru":"Скопировать состояние в каждый компонент и синхронизировать через useEffect","en":"Duplicate the state in both and sync with useEffect"},{"uz":"Global window obyektida saqlash","ru":"Хранить в глобальном объекте window","en":"Store it on the global window object"},{"uz":"localStorage orqali almashish","ru":"Обмениваться через localStorage","en":"Exchange it through localStorage"}]'::jsonb, 0, '{"uz":"Umumiy holat ularning umumiy otasida bo‘lishi kerak. Agar prop drilling juda chuqurlashsa, Context yoki state-menejer (Zustand, Redux) ko‘rib chiqiladi.","ru":"Общее состояние должно жить в общем родителе. Если prop drilling становится слишком глубоким, рассматривают Context или стейт-менеджер (Zustand, Redux).","en":"Shared state belongs in the common parent. If prop drilling becomes too deep, consider Context or a state manager (Zustand, Redux)."}'::jsonb, 15),
  ('react-16', 'react', 'medium', '{"uz":"Context value o‘zgarganda nima bo‘ladi?","ru":"Что происходит, когда меняется value у Context?","en":"What happens when a Context value changes?"}'::jsonb, '<ThemeContext.Provider value={{ theme, toggle }}>
  <App />
</ThemeContext.Provider>', '[{"uz":"Hech narsa, Context faqat bir marta o‘qiladi","ru":"Ничего, Context читается один раз","en":"Nothing, Context is read only once"},{"uz":"Butun sahifa qayta yuklanadi","ru":"Вся страница перезагружается","en":"The whole page reloads"},{"uz":"Faqat Provider qayta render bo‘ladi","ru":"Перерисовывается только Provider","en":"Only the Provider re-renders"},{"uz":"Shu contextni useContext orqali o‘qiydigan barcha komponentlar qayta render bo‘ladi","ru":"Все компоненты, читающие этот контекст через useContext, перерисовываются","en":"All components that read this context with useContext re-render"}]'::jsonb, 3, '{"uz":"Misolda har renderda yangi obyekt yaratiladi va iste’molchilar keraksiz render bo‘ladi. value’ni useMemo bilan barqarorlashtirish yoki contextni bo‘lish yordam beradi.","ru":"В примере на каждом рендере создаётся новый объект, и потребители лишний раз перерисовываются. Помогает стабилизация value через useMemo или разделение контекста.","en":"In the example a new object is created every render, causing extra consumer renders. Stabilize value with useMemo or split the context."}'::jsonb, 15),
  ('react-17', 'react', 'hard', '{"uz":"Nega hook’larni shart (if) yoki sikl ichida chaqirish mumkin emas?","ru":"Почему хуки нельзя вызывать внутри условий или циклов?","en":"Why can hooks not be called inside conditions or loops?"}'::jsonb, 'if (isLoggedIn) {
  const [name, setName] = useState("")
}', '[{"uz":"Bu sintaksis xatosi hisoblanadi","ru":"Это синтаксическая ошибка","en":"It is a syntax error"},{"uz":"React hook holatini chaqiruv tartibi bo‘yicha bog‘laydi; tartib renderlar orasida o‘zgarsa, holatlar aralashib ketadi","ru":"React связывает состояние хуков с порядком вызовов; если порядок меняется между рендерами, состояния путаются","en":"React associates hook state with call order; if the order changes between renders, state gets mixed up"},{"uz":"Hook’lar sekin ishlaydi","ru":"Хуки работают медленно","en":"Hooks are slow"},{"uz":"if ichida useState faqat class komponentlarda ishlaydi","ru":"useState внутри if работает только в классах","en":"useState inside if only works in class components"}]'::jsonb, 1, '{"uz":"Har bir hook ichki ro‘yxatdagi indeksiga ko‘ra topiladi. Shuning uchun hook’lar har doim komponentning yuqori darajasida, bir xil tartibda chaqirilishi kerak.","ru":"Каждый хук находится по своему индексу во внутреннем списке. Поэтому хуки всегда вызываются на верхнем уровне компонента в одном и том же порядке.","en":"Each hook is looked up by its index in an internal list. That is why hooks must always be called at the top level, in the same order."}'::jsonb, 20),
  ('react-18', 'react', 'hard', '{"uz":"count = 0 bo‘lganda bu komponent nimani render qiladi?","ru":"Что отрендерит этот компонент при count = 0?","en":"What does this component render when count = 0?"}'::jsonb, 'return <div>{count && <p>New messages: {count}</p>}</div>', '[{"uz":"Bo‘sh <div>","ru":"Пустой <div>","en":"An empty <div>"},{"uz":"<p>New messages: 0</p>","ru":"<p>New messages: 0</p>","en":"<p>New messages: 0</p>"},{"uz":"Ekranda “0” raqami","ru":"Цифру «0» на экране","en":"The digit \"0\" on screen"},{"uz":"Xato yuz beradi","ru":"Произойдёт ошибка","en":"An error is thrown"}]'::jsonb, 2, '{"uz":"0 && ... ifodasi 0 ni qaytaradi va React raqamlarni render qiladi. To‘g‘ri yozish: {count > 0 && ...} yoki ternary operator.","ru":"Выражение 0 && ... возвращает 0, а React рендерит числа. Правильно: {count > 0 && ...} или тернарный оператор.","en":"0 && ... evaluates to 0, and React renders numbers. Write {count > 0 && ...} or use a ternary instead."}'::jsonb, 20),
  ('react-19', 'react', 'medium', '{"uz":"Reconciliation jarayonida React nima qiladi?","ru":"Что делает React в процессе reconciliation (согласования)?","en":"What does React do during reconciliation?"}'::jsonb, null, '[{"uz":"Yangi element daraxtini oldingisi bilan solishtiradi va DOM’ga faqat zarur o‘zgarishlarni kiritadi","ru":"Сравнивает новое дерево элементов с предыдущим и вносит в DOM только необходимые изменения","en":"Compares the new element tree with the previous one and applies only the necessary DOM changes"},{"uz":"Har renderda butun DOM’ni noldan qayta yaratadi","ru":"На каждом рендере пересоздаёт весь DOM с нуля","en":"Recreates the entire DOM from scratch on each render"},{"uz":"Serverdagi ma’lumotlar bilan sinxronlaydi","ru":"Синхронизирует данные с сервером","en":"Synchronizes data with the server"},{"uz":"CSS fayllarini birlashtiradi","ru":"Объединяет CSS-файлы","en":"Merges CSS files"}]'::jsonb, 0, '{"uz":"Agar element turi o‘zgarsa, React kichik daraxtni qayta yaratadi; tur va key bir xil bo‘lsa — mavjud DOM tugunini yangilaydi.","ru":"Если тип элемента изменился, React пересоздаёт поддерево; при совпадении типа и key — обновляет существующий DOM-узел.","en":"If the element type changes, React rebuilds that subtree; if type and key match, it updates the existing DOM node."}'::jsonb, 15),
  ('react-20', 'react', 'hard', '{"uz":"useLayoutEffect useEffect’dan nimasi bilan farq qiladi?","ru":"Чем useLayoutEffect отличается от useEffect?","en":"How does useLayoutEffect differ from useEffect?"}'::jsonb, null, '[{"uz":"U faqat serverda ishlaydi","ru":"Работает только на сервере","en":"It only runs on the server"},{"uz":"U renderdan oldin ishlaydi","ru":"Выполняется до рендера","en":"It runs before render"},{"uz":"Farqi yo‘q, bu eskirgan nom","ru":"Разницы нет, это устаревшее имя","en":"No difference, it is a deprecated alias"},{"uz":"DOM o‘zgarishlaridan keyin, lekin brauzer ekranni chizishidan oldin sinxron ishlaydi","ru":"Выполняется синхронно после изменений DOM, но до отрисовки браузером","en":"It runs synchronously after DOM mutations but before the browser paints"}]'::jsonb, 3, '{"uz":"useLayoutEffect element o‘lchamini o‘lchab, pozitsiyani “miltillamasdan” to‘g‘rilash (tooltip) uchun kerak. U paint’ni bloklaydi, shuning uchun odatda useEffect afzal.","ru":"useLayoutEffect нужен, чтобы измерить элемент и поправить позицию без «мигания» (тултип). Он блокирует отрисовку, поэтому обычно предпочтителен useEffect.","en":"useLayoutEffect is for measuring layout and adjusting position without flicker (e.g. tooltips). It blocks painting, so useEffect is usually preferred."}'::jsonb, 20),
  ('ts-01', 'typescript', 'medium', '{"uz":"interface’ni type alias’dan ajratib turadigan imkoniyat qaysi?","ru":"Какая возможность есть у interface, но нет у type alias?","en":"Which capability does an interface have that a type alias does not?"}'::jsonb, 'interface User { name: string }
interface User { age: number }
// User = { name: string; age: number }', '[{"uz":"Union tiplarni ifodalash","ru":"Описание union-типов","en":"Expressing union types"},{"uz":"Declaration merging — bir xil nomli e’lonlar birlashtiriladi","ru":"Declaration merging — одноимённые объявления объединяются","en":"Declaration merging — declarations with the same name are merged"},{"uz":"Primitiv tiplarga nom berish","ru":"Псевдонимы для примитивов","en":"Aliasing primitive types"},{"uz":"Tuple tiplarni ifodalash","ru":"Описание кортежей","en":"Expressing tuple types"}]'::jsonb, 1, '{"uz":"Ikki marta e’lon qilingan interface birlashadi; type esa “Duplicate identifier” xatosini beradi. Union, tuple va primitiv aliaslar faqat type orqali yoziladi.","ru":"Дважды объявленный interface объединяется; type вызовет ошибку «Duplicate identifier». Union, кортежи и алиасы примитивов пишутся только через type.","en":"An interface declared twice is merged; a type alias gives a \"Duplicate identifier\" error. Unions, tuples and primitive aliases require type."}'::jsonb, 15),
  ('ts-02', 'typescript', 'easy', '{"uz":"unknown va any o‘rtasidagi farq nima?","ru":"В чём разница между unknown и any?","en":"What is the difference between unknown and any?"}'::jsonb, 'let a: any = ''x''
let u: unknown = ''x''
a.toUpperCase() // ok
u.toUpperCase() // error', '[{"uz":"unknown bilan ishlashdan oldin tipni toraytirish (narrowing) kerak; any esa tekshiruvni butunlay o‘chiradi","ru":"С unknown нужно сначала сузить тип (narrowing); any полностью отключает проверку","en":"unknown requires narrowing before use; any disables type checking entirely"},{"uz":"Ular bir xil","ru":"Они одинаковы","en":"They are the same"},{"uz":"unknown faqat null qabul qiladi","ru":"unknown принимает только null","en":"unknown only accepts null"},{"uz":"any faqat raqamlar uchun","ru":"any только для чисел","en":"any is only for numbers"}]'::jsonb, 0, '{"uz":"unknown — xavfsiz “top type”: unga istalgan qiymat beriladi, lekin typeof, instanceof yoki type guard’siz ishlatib bo‘lmaydi.","ru":"unknown — безопасный «top type»: присвоить можно что угодно, но использовать нельзя без typeof, instanceof или type guard.","en":"unknown is the safe top type: anything can be assigned to it, but it cannot be used without typeof, instanceof or a type guard."}'::jsonb, 10),
  ('ts-03', 'typescript', 'easy', '{"uz":"user.age xususiyatining tipi qanday?","ru":"Какой тип у свойства user.age?","en":"What is the type of user.age?"}'::jsonb, 'interface User {
  name: string
  age?: number
}', '[{"uz":"number","ru":"number","en":"number"},{"uz":"number | null","ru":"number | null","en":"number | null"},{"uz":"number | undefined","ru":"number | undefined","en":"number | undefined"},{"uz":"any","ru":"any","en":"any"}]'::jsonb, 2, '{"uz":"? belgisi xususiyatni ixtiyoriy qiladi — u yo‘q bo‘lishi mumkin, shuning uchun o‘qilganda tipi number | undefined.","ru":"Знак ? делает свойство необязательным — его может не быть, поэтому при чтении тип number | undefined.","en":"The ? makes the property optional — it may be missing, so reading it yields number | undefined."}'::jsonb, 10),
  ('ts-04', 'typescript', 'medium', '{"uz":"TypeScript bu kodga qanday munosabatda?","ru":"Как TypeScript отнесётся к этому коду?","en":"How does TypeScript treat this code?"}'::jsonb, 'function format(x: string | number) {
  if (typeof x === ''string'') {
    return x.toUpperCase()
  }
  return x.toFixed(2)
}', '[{"uz":"Xato: union tipida metodlarni chaqirib bo‘lmaydi","ru":"Ошибка: у union-типа нельзя вызывать методы","en":"Error: methods cannot be called on a union type"},{"uz":"Xato: typeof faqat runtime’da ishlaydi","ru":"Ошибка: typeof работает только в runtime","en":"Error: typeof only works at runtime"},{"uz":"any sifatida qabul qiladi","ru":"Воспринимает как any","en":"Treats x as any"},{"uz":"Xatosiz: typeof tekshiruvi har bir shoxda tipni toraytiradi","ru":"Без ошибок: проверка typeof сужает тип в каждой ветке","en":"No errors: the typeof check narrows the type in each branch"}]'::jsonb, 3, '{"uz":"Control flow analysis: if ichida x — string, undan keyin esa qolgan variant — number. Bu “type narrowing” deyiladi.","ru":"Анализ потока управления: внутри if x — string, после него остаётся number. Это называется сужением типа (narrowing).","en":"Control-flow analysis: inside the if x is string, afterwards the remaining member is number. This is called type narrowing."}'::jsonb, 15),
  ('ts-05', 'typescript', 'medium', '{"uz":"Bu generic funksiyaning any’dan afzalligi nimada?","ru":"В чём преимущество этой generic-функции перед any?","en":"What is the advantage of this generic function over using any?"}'::jsonb, 'function first<T>(items: T[]): T | undefined {
  return items[0]
}
const n = first([1, 2, 3])', '[{"uz":"U tezroq ishlaydi","ru":"Работает быстрее","en":"It runs faster"},{"uz":"Kiruvchi va chiquvchi tiplar o‘rtasidagi bog‘liqlik saqlanadi: n ning tipi number | undefined","ru":"Сохраняется связь между входным и выходным типом: n имеет тип number | undefined","en":"It preserves the relationship between input and output types: n is number | undefined"},{"uz":"Runtime’da massivni tekshiradi","ru":"Проверяет массив в runtime","en":"It validates the array at runtime"},{"uz":"Faqat raqamli massivlarni qabul qiladi","ru":"Принимает только числовые массивы","en":"It only accepts numeric arrays"}]'::jsonb, 1, '{"uz":"T chaqiruv paytida avtomatik aniqlanadi (inference). any bo‘lsa, natija tipi yo‘qoladi va xatolar kompilyatsiyada aniqlanmaydi.","ru":"T выводится автоматически при вызове (inference). С any тип результата теряется, и ошибки не ловятся при компиляции.","en":"T is inferred at the call site. With any, the result type is lost and mistakes are not caught at compile time."}'::jsonb, 15),
  ('ts-06', 'typescript', 'medium', '{"uz":"Partial<User> qanday tip yaratadi?","ru":"Какой тип создаёт Partial<User>?","en":"What type does Partial<User> produce?"}'::jsonb, 'interface User { id: number; name: string; email: string }
type Draft = Partial<User>', '[{"uz":"Faqat birinchi xususiyatni o‘z ichiga olgan tip","ru":"Тип только с первым свойством","en":"A type with only the first property"},{"uz":"Barcha xususiyatlari readonly bo‘lgan tip","ru":"Тип со всеми свойствами readonly","en":"A type with all properties readonly"},{"uz":"Barcha xususiyatlari ixtiyoriy (?) bo‘lgan tip","ru":"Тип, у которого все свойства необязательные (?)","en":"A type where every property is optional (?)"},{"uz":"Barcha xususiyatlari string bo‘lgan tip","ru":"Тип, у которого все свойства string","en":"A type where every property is a string"}]'::jsonb, 2, '{"uz":"Partial<T> = { [K in keyof T]?: T[K] }. Odatda yangilash (update) funksiyalari parametrlari uchun ishlatiladi. Teskarisi — Required<T>.","ru":"Partial<T> = { [K in keyof T]?: T[K] }. Часто используется для параметров функций обновления. Обратный тип — Required<T>.","en":"Partial<T> = { [K in keyof T]?: T[K] }. Commonly used for update-function parameters. The opposite is Required<T>."}'::jsonb, 15),
  ('ts-07', 'typescript', 'hard', '{"uz":"Key tipi nimaga teng?","ru":"Чему равен тип Key?","en":"What is the type Key?"}'::jsonb, 'const config = { host: ''localhost'', port: 5432 }
type Key = keyof typeof config', '[{"uz":"\"host\" | \"port\"","ru":"\"host\" | \"port\"","en":"\"host\" | \"port\""},{"uz":"string","ru":"string","en":"string"},{"uz":"{ host: string; port: number }","ru":"{ host: string; port: number }","en":"{ host: string; port: number }"},{"uz":"string | number","ru":"string | number","en":"string | number"}]'::jsonb, 0, '{"uz":"typeof config qiymatdan tip oladi, keyof esa uning kalitlari birlashmasini (union) qaytaradi. Bu juftlik konfiguratsiya obyektlari bilan ishlashda juda foydali.","ru":"typeof config получает тип из значения, а keyof возвращает объединение его ключей. Эта связка очень полезна для объектов конфигурации.","en":"typeof config extracts a type from a value and keyof returns the union of its keys. This combo is very useful with config objects."}'::jsonb, 20),
  ('ts-08', 'typescript', 'hard', '{"uz":"Bu kodda never tipi qanday vazifani bajaradi?","ru":"Какую задачу решает тип never в этом коде?","en":"What role does the never type play in this code?"}'::jsonb, 'type Shape = { kind: ''circle''; r: number } | { kind: ''square''; a: number }

function area(s: Shape) {
  switch (s.kind) {
    case ''circle'': return Math.PI * s.r ** 2
    case ''square'': return s.a ** 2
    default:
      const check: never = s
      return check
  }
}', '[{"uz":"Funksiyani asinxron qiladi","ru":"Делает функцию асинхронной","en":"Makes the function async"},{"uz":"Runtime’da xato tashlaydi","ru":"Бросает ошибку в runtime","en":"Throws an error at runtime"},{"uz":"Hech qanday vazifa bajarmaydi","ru":"Ничего не делает","en":"It does nothing"},{"uz":"Exhaustive check: Shape’ga yangi variant qo‘shilsa va u qayta ishlanmasa, kompilyatsiya xatosi chiqadi","ru":"Проверка полноты: если в Shape добавят вариант и не обработают его, будет ошибка компиляции","en":"Exhaustiveness check: if a new Shape variant is added but not handled, compilation fails"}]'::jsonb, 3, '{"uz":"Barcha holatlar ko‘rib chiqilganda s ning tipi never’ga torayadi. Yangi variant (masalan, triangle) qo‘shilsa, uni never’ga tayinlab bo‘lmaydi va TS xato beradi.","ru":"Когда все варианты обработаны, тип s сужается до never. Если добавить новый (например, triangle), его нельзя присвоить never, и TS выдаст ошибку.","en":"When all cases are handled, s narrows to never. Adding a new variant (e.g. triangle) makes the assignment to never fail at compile time."}'::jsonb, 20),
  ('ts-09', 'typescript', 'medium', '{"uz":"as const nima qiladi?","ru":"Что делает as const?","en":"What does as const do?"}'::jsonb, 'const roles = [''admin'', ''student''] as const
type Role = typeof roles[number]', '[{"uz":"Massivni runtime’da muzlatadi (Object.freeze)","ru":"Замораживает массив в runtime (Object.freeze)","en":"Freezes the array at runtime (Object.freeze)"},{"uz":"Eng tor literal tiplarni chiqaradi va readonly qiladi: Role = \"admin\" | \"student\"","ru":"Выводит самые узкие литеральные типы и делает readonly: Role = \"admin\" | \"student\"","en":"Infers the narrowest literal types and makes it readonly: Role = \"admin\" | \"student\""},{"uz":"Massivni const o‘zgaruvchiga aylantiradi","ru":"Превращает массив в const-переменную","en":"Turns the array into a const variable"},{"uz":"Role tipini string qiladi","ru":"Делает тип Role равным string","en":"Makes Role equal to string"}]'::jsonb, 1, '{"uz":"as const bo‘lmasa, tip string[] bo‘lardi. U faqat kompilyatsiya vaqtidagi tiplarga ta’sir qiladi, runtime’da obyektni muzlatmaydi.","ru":"Без as const тип был бы string[]. Он влияет только на типы при компиляции и не замораживает объект в runtime.","en":"Without as const the type would be string[]. It only affects compile-time types and does not freeze anything at runtime."}'::jsonb, 15),
  ('ts-10', 'typescript', 'hard', '{"uz":"PublicUser tipi qanday?","ru":"Каким будет тип PublicUser?","en":"What is the PublicUser type?"}'::jsonb, 'interface User {
  id: number
  name: string
  password: string
}
type PublicUser = Omit<User, ''password''>', '[{"uz":"{ password: string }","ru":"{ password: string }","en":"{ password: string }"},{"uz":"{ id: number; name: string; password?: string }","ru":"{ id: number; name: string; password?: string }","en":"{ id: number; name: string; password?: string }"},{"uz":"{ id: number; name: string }","ru":"{ id: number; name: string }","en":"{ id: number; name: string }"},{"uz":"never","ru":"never","en":"never"}]'::jsonb, 2, '{"uz":"Omit<T, K> T dan K kalitlarini olib tashlaydi. Pick<T, K> esa aksincha — faqat ko‘rsatilgan kalitlarni qoldiradi.","ru":"Omit<T, K> удаляет из T ключи K. Pick<T, K> делает обратное — оставляет только указанные ключи.","en":"Omit<T, K> removes keys K from T. Pick<T, K> does the opposite — keeps only the listed keys."}'::jsonb, 20),
  ('scss-01', 'scss', 'easy', '{"uz":"SCSS’da o‘zgaruvchi qanday e’lon qilinadi?","ru":"Как объявить переменную в SCSS?","en":"How do you declare a variable in SCSS?"}'::jsonb, null, '[{"uz":"$primary: #6366f1;","ru":"$primary: #6366f1;","en":"$primary: #6366f1;"},{"uz":"@primary: #6366f1;","ru":"@primary: #6366f1;","en":"@primary: #6366f1;"},{"uz":"var primary = #6366f1;","ru":"var primary = #6366f1;","en":"var primary = #6366f1;"},{"uz":"--primary = #6366f1;","ru":"--primary = #6366f1;","en":"--primary = #6366f1;"}]'::jsonb, 0, '{"uz":"Sass o‘zgaruvchilari $ bilan boshlanadi va kompilyatsiya vaqtida qiymatga almashtiriladi. @primary — Less sintaksisi, --primary esa CSS custom property.","ru":"Переменные Sass начинаются с $ и подставляются при компиляции. @primary — синтаксис Less, --primary — CSS custom property.","en":"Sass variables start with $ and are replaced at compile time. @primary is Less syntax and --primary is a CSS custom property."}'::jsonb, 10),
  ('scss-02', 'scss', 'easy', '{"uz":"Bu SCSS qanday CSS’ga kompilyatsiya qilinadi?","ru":"Во что скомпилируется этот SCSS?","en":"What CSS does this SCSS compile to?"}'::jsonb, '.btn {
  color: white;
  &:hover { color: cyan; }
  &--primary { background: blue; }
}', '[{"uz":".btn { color: white } .btn :hover { color: cyan } .btn --primary { background: blue }","ru":".btn { color: white } .btn :hover { color: cyan } .btn --primary { background: blue }","en":".btn { color: white } .btn :hover { color: cyan } .btn --primary { background: blue }"},{"uz":".btn { color: white } :hover { color: cyan } --primary { background: blue }","ru":".btn { color: white } :hover { color: cyan } --primary { background: blue }","en":".btn { color: white } :hover { color: cyan } --primary { background: blue }"},{"uz":".btn { color: white } .btn:hover { color: cyan } .btn--primary { background: blue }","ru":".btn { color: white } .btn:hover { color: cyan } .btn--primary { background: blue }","en":".btn { color: white } .btn:hover { color: cyan } .btn--primary { background: blue }"},{"uz":"Kompilyatsiya xatosi","ru":"Ошибка компиляции","en":"A compilation error"}]'::jsonb, 2, '{"uz":"& — ota selektorga havola. U bo‘sh joysiz qo‘shiladi, shuning uchun BEM modifikatorlari (&--primary) va pseudo-klasslar (&:hover) uchun qulay.","ru":"& — ссылка на родительский селектор. Он подставляется без пробела, поэтому удобен для BEM-модификаторов (&--primary) и псевдоклассов (&:hover).","en":"& references the parent selector and is inserted without a space — perfect for BEM modifiers (&--primary) and pseudo-classes (&:hover)."}'::jsonb, 10),
  ('scss-03', 'scss', 'medium', '{"uz":"Bu kod nima qiladi?","ru":"Что делает этот код?","en":"What does this code do?"}'::jsonb, '@mixin flex-center($gap: 8px) {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: $gap;
}

.toolbar { @include flex-center(16px); }', '[{"uz":".toolbar’ni flex-center klassidan meros oldiradi","ru":"Наследует .toolbar от класса flex-center","en":"Makes .toolbar inherit from a flex-center class"},{"uz":"Qayta ishlatiladigan stillar blokini parametr bilan .toolbar ichiga qo‘shadi","ru":"Вставляет переиспользуемый блок стилей с параметром внутрь .toolbar","en":"Inserts a reusable, parameterized block of styles into .toolbar"},{"uz":"CSS’da yangi @mixin qoidasini yaratadi","ru":"Создаёт в CSS новое правило @mixin","en":"Creates a new @mixin rule in the output CSS"},{"uz":"Faqat gap’ni 16px qiladi","ru":"Только устанавливает gap 16px","en":"Only sets gap to 16px"}]'::jsonb, 1, '{"uz":"@mixin stillar blokini e’lon qiladi (argumentlar va default qiymatlar bilan), @include esa uni chaqiradi. Natijaviy CSS’da mixin’ning o‘zi chiqmaydi.","ru":"@mixin объявляет блок стилей (с аргументами и значениями по умолчанию), @include его подключает. Сам mixin в итоговый CSS не попадает.","en":"@mixin declares a block of styles (with arguments and defaults) and @include uses it. The mixin itself is not emitted to CSS."}'::jsonb, 15),
  ('scss-04', 'scss', 'medium', '{"uz":"@extend va @mixin o‘rtasidagi asosiy farq nima?","ru":"В чём главное различие между @extend и @mixin?","en":"What is the key difference between @extend and @mixin?"}'::jsonb, null, '[{"uz":"Farqi yo‘q","ru":"Разницы нет","en":"There is no difference"},{"uz":"@mixin faqat ranglar uchun","ru":"@mixin только для цветов","en":"@mixin is only for colors"},{"uz":"@extend argument qabul qiladi, @mixin qabul qilmaydi","ru":"@extend принимает аргументы, @mixin — нет","en":"@extend accepts arguments, @mixin does not"},{"uz":"@extend selektorlarni bitta qoidaga guruhlaydi, @mixin esa stillarni har bir joyga nusxalaydi va argument qabul qiladi","ru":"@extend группирует селекторы в одно правило, а @mixin копирует стили в каждое место и принимает аргументы","en":"@extend groups selectors into one shared rule, while @mixin copies styles into each place and accepts arguments"}]'::jsonb, 3, '{"uz":"@extend kamroq CSS hosil qiladi, lekin kutilmagan selektor zanjirlariga olib kelishi va media-so‘rovlar ichida cheklangan bo‘lishi mumkin. Mixin’lar oldindan aytib bo‘ladigan va moslashuvchan.","ru":"@extend даёт меньше CSS, но может порождать неожиданные цепочки селекторов и ограничен внутри медиазапросов. Миксины предсказуемее и гибче.","en":"@extend produces less CSS but can create unexpected selector chains and is restricted inside media queries. Mixins are more predictable and flexible."}'::jsonb, 15),
  ('scss-05', 'scss', 'medium', '{"uz":"Nima uchun fayl nomi _variables.scss kabi pastki chiziq bilan boshlanadi?","ru":"Почему имя файла начинается с подчёркивания, например _variables.scss?","en":"Why does a file name start with an underscore, like _variables.scss?"}'::jsonb, null, '[{"uz":"Bu partial: u alohida CSS faylga kompilyatsiya qilinmaydi, faqat boshqa fayllarga @use orqali ulanadi","ru":"Это partial: он не компилируется в отдельный CSS-файл, а только подключается в другие через @use","en":"It is a partial: it is not compiled into its own CSS file and is only loaded by other files via @use"},{"uz":"Fayl yashirin bo‘ladi","ru":"Файл становится скрытым","en":"The file becomes hidden"},{"uz":"Fayl birinchi bo‘lib yuklanadi","ru":"Файл загружается первым","en":"The file is loaded first"},{"uz":"Bu majburiy nomlash qoidasi, aks holda xato bo‘ladi","ru":"Это обязательное правило, иначе будет ошибка","en":"It is mandatory naming, otherwise compilation fails"}]'::jsonb, 0, '{"uz":"Partial’lar kodni modullarga ajratadi. Import qilishda pastki chiziq va kengaytma yozilmaydi: @use \"variables\".","ru":"Partials разбивают код на модули. При подключении подчёркивание и расширение не пишут: @use \"variables\".","en":"Partials split code into modules. When loading them, omit the underscore and extension: @use \"variables\"."}'::jsonb, 15),
  ('scss-06', 'scss', 'hard', '{"uz":"Zamonaviy Sass’da @use ning @import’dan afzalligi nimada?","ru":"Чем @use лучше @import в современном Sass?","en":"Why is @use preferred over @import in modern Sass?"}'::jsonb, '@use ''sass:math'';
@use ''tokens'' as t;

.card { padding: t.$space-4; width: math.div(100%, 3); }', '[{"uz":"@use tezroq yuklanadi, boshqa farqi yo‘q","ru":"@use быстрее загружается, других отличий нет","en":"@use loads faster and that is the only difference"},{"uz":"@use CSS fayllarni brauzerda import qiladi","ru":"@use импортирует CSS-файлы в браузере","en":"@use imports CSS files in the browser"},{"uz":"@use modulni bir marta yuklaydi va a’zolarini namespace orqali beradi; @import global va eskirgan (deprecated)","ru":"@use загружает модуль один раз и даёт доступ к членам через namespace; @import глобальный и устарел","en":"@use loads a module once and exposes its members through a namespace; @import is global and deprecated"},{"uz":"@import faqat partial’lar uchun ishlaydi","ru":"@import работает только с partials","en":"@import only works with partials"}]'::jsonb, 2, '{"uz":"@import barcha o‘zgaruvchilarni global maydonga tashlaydi va nom to‘qnashuviga olib keladi. @use namespace (t.$space-4) va private a’zolarni (-/_ prefiks) qo‘llab-quvvatlaydi.","ru":"@import сваливает все переменные в глобальную область и вызывает конфликты имён. @use поддерживает namespace (t.$space-4) и приватные члены (префикс -/_).","en":"@import dumps everything into the global scope causing name clashes. @use supports namespaces (t.$space-4) and private members (-/_ prefix)."}'::jsonb, 20),
  ('scss-07', 'scss', 'hard', '{"uz":".title uchun font-size qancha bo‘ladi?","ru":"Какой font-size получит .title?","en":"What font-size will .title get?"}'::jsonb, '@use ''sass:math'';

@function rem($px, $base: 16px) {
  @return math.div($px, $base) * 1rem;
}

.title { font-size: rem(24px); }', '[{"uz":"24rem","ru":"24rem","en":"24rem"},{"uz":"1.5rem","ru":"1.5rem","en":"1.5rem"},{"uz":"0.67rem","ru":"0.67rem","en":"0.67rem"},{"uz":"384rem","ru":"384rem","en":"384rem"}]'::jsonb, 1, '{"uz":"@function qiymat qaytaradi (@return). 24px / 16px = 1.5 (birliksiz), keyin 1rem’ga ko‘paytiriladi → 1.5rem.","ru":"@function возвращает значение через @return. 24px / 16px = 1.5 (без единиц), затем умножаем на 1rem → 1.5rem.","en":"@function returns a value with @return. 24px / 16px = 1.5 (unitless), multiplied by 1rem → 1.5rem."}'::jsonb, 20),
  ('scss-08', 'scss', 'medium', '{"uz":"Bu kod qanday CSS hosil qiladi?","ru":"Какой CSS сгенерирует этот код?","en":"What CSS does this code generate?"}'::jsonb, '$colors: (primary: #6366f1, danger: #ef4444);

@each $name, $color in $colors {
  .text-#{$name} { color: $color; }
}', '[{"uz":"Bitta .text-colors klassi","ru":"Один класс .text-colors","en":"A single .text-colors class"},{"uz":"Xato: map’ni aylanib chiqib bo‘lmaydi","ru":"Ошибка: по map нельзя итерироваться","en":"An error: maps cannot be iterated"},{"uz":".text-$name { color: $color }","ru":".text-$name { color: $color }","en":".text-$name { color: $color }"},{"uz":".text-primary { color: #6366f1 } .text-danger { color: #ef4444 }","ru":".text-primary { color: #6366f1 } .text-danger { color: #ef4444 }","en":".text-primary { color: #6366f1 } .text-danger { color: #ef4444 }"}]'::jsonb, 3, '{"uz":"@each map’ning har bir kalit-qiymat juftligini aylanib chiqadi, #{} — interpolatsiya bo‘lib, o‘zgaruvchini selektor nomiga qo‘yadi.","ru":"@each перебирает пары ключ-значение map, а #{} — интерполяция, подставляющая переменную в имя селектора.","en":"@each iterates over key/value pairs of a map and #{} interpolation inserts the variable into the selector name."}'::jsonb, 15),
  ('scss-09', 'scss', 'hard', '{"uz":"%placeholder selektori qanday xususiyatga ega?","ru":"Какая особенность у селектора %placeholder?","en":"What is special about a %placeholder selector?"}'::jsonb, '%btn-base { padding: 8px 16px; border-radius: 8px; }

.btn-primary { @extend %btn-base; background: blue; }', '[{"uz":"U faqat @extend qilinganda CSS’ga chiqadi; o‘zi alohida klass sifatida chiqmaydi","ru":"Попадает в CSS только при @extend; сам по себе как класс не выводится","en":"It is only emitted when extended; it never appears in CSS as a class on its own"},{"uz":"U foiz (%) qiymatlarini hisoblaydi","ru":"Вычисляет процентные значения","en":"It calculates percentage values"},{"uz":"U HTML’dagi placeholder atributini stillaydi","ru":"Стилизует атрибут placeholder в HTML","en":"It styles the placeholder attribute in HTML"},{"uz":"U @include bilan ishlatiladi","ru":"Используется через @include","en":"It is used with @include"}]'::jsonb, 0, '{"uz":"Placeholder — @extend uchun mo‘ljallangan “jim” selektor. Agar u hech qayerda extend qilinmasa, CSS’da umuman paydo bo‘lmaydi.","ru":"Placeholder — «тихий» селектор для @extend. Если его нигде не расширили, в CSS он не появится вовсе.","en":"A placeholder is a \"silent\" selector meant for @extend. If nothing extends it, it does not appear in the CSS at all."}'::jsonb, 20),
  ('scss-10', 'scss', 'medium', '{"uz":"Zamonaviy Dart Sass’da bo‘lishni (division) to‘g‘ri yozish usuli qaysi?","ru":"Как правильно записать деление в современном Dart Sass?","en":"What is the correct way to divide in modern Dart Sass?"}'::jsonb, null, '[{"uz":"$half: $width / 2;","ru":"$half: $width / 2;","en":"$half: $width / 2;"},{"uz":"$half: divide($width, 2);","ru":"$half: divide($width, 2);","en":"$half: divide($width, 2);"},{"uz":"@use ''sass:math'';  $half: math.div($width, 2);","ru":"@use ''sass:math'';  $half: math.div($width, 2);","en":"@use ''sass:math'';  $half: math.div($width, 2);"},{"uz":"$half: $width % 2;","ru":"$half: $width % 2;","en":"$half: $width % 2;"}]'::jsonb, 2, '{"uz":"/ belgisi bilan bo‘lish eskirgan, chunki CSS’da / ajratuvchi sifatida ham ishlatiladi (masalan, grid-area: 1 / 3). math.div() aniq va kelajakka mos.","ru":"Деление через / устарело, так как / в CSS используется и как разделитель (например, grid-area: 1 / 3). math.div() однозначен и рекомендован.","en":"Division with / is deprecated because / is also a separator in CSS (e.g. grid-area: 1 / 3). math.div() is unambiguous and future-proof."}'::jsonb, 15),
  ('tw-01', 'tailwind', 'easy', '{"uz":"Tailwind CSS’ning “utility-first” yondashuvi nimani anglatadi?","ru":"Что означает подход «utility-first» в Tailwind CSS?","en":"What does the \"utility-first\" approach in Tailwind CSS mean?"}'::jsonb, null, '[{"uz":"Tayyor komponentlar (Button, Card) to‘plami","ru":"Набор готовых компонентов (Button, Card)","en":"A set of ready-made components (Button, Card)"},{"uz":"Interfeysni kichik, bir vazifali klasslarni (p-4, flex, text-center) to‘g‘ridan-to‘g‘ri markup’da birlashtirib qurish","ru":"Построение интерфейса комбинацией маленьких одноцелевых классов (p-4, flex, text-center) прямо в разметке","en":"Building UIs by composing small single-purpose classes (p-4, flex, text-center) directly in markup"},{"uz":"Barcha stillarni JavaScript’da yozish","ru":"Написание всех стилей на JavaScript","en":"Writing all styles in JavaScript"},{"uz":"Inline style atributlaridan foydalanish","ru":"Использование inline-атрибута style","en":"Using inline style attributes"}]'::jsonb, 1, '{"uz":"Inline style’dan farqli o‘laroq, utility’lar dizayn tizimi (spacing, ranglar) bilan cheklangan va hover:, md: kabi variantlarni qo‘llab-quvvatlaydi.","ru":"В отличие от inline-стилей, утилиты ограничены дизайн-системой (отступы, цвета) и поддерживают варианты вроде hover:, md:.","en":"Unlike inline styles, utilities are constrained by a design system (spacing, colors) and support variants like hover: and md:."}'::jsonb, 10),
  ('tw-02', 'tailwind', 'easy', '{"uz":"md:flex klassi qachon qo‘llanadi?","ru":"Когда применяется класс md:flex?","en":"When is the md:flex class applied?"}'::jsonb, '<div class="block md:flex">...</div>', '[{"uz":"Faqat mobil ekranlarda","ru":"Только на мобильных экранах","en":"Only on mobile screens"},{"uz":"Faqat 768px dan kichik ekranlarda","ru":"Только на экранах меньше 768px","en":"Only on screens narrower than 768px"},{"uz":"Faqat planshetlarda (768–1024px)","ru":"Только на планшетах (768–1024px)","en":"Only on tablets (768–1024px)"},{"uz":"Ekran kengligi 768px va undan katta bo‘lganda","ru":"При ширине экрана от 768px и больше","en":"When the viewport is 768px wide or wider"}]'::jsonb, 3, '{"uz":"Tailwind breakpoint’lari min-width asosida ishlaydi: md: = @media (min-width: 768px). Kichik ekranlarda block, 768px dan boshlab flex bo‘ladi.","ru":"Брейкпоинты Tailwind основаны на min-width: md: = @media (min-width: 768px). На маленьких экранах — block, начиная с 768px — flex.","en":"Tailwind breakpoints are min-width based: md: = @media (min-width: 768px). It is block on small screens and flex from 768px up."}'::jsonb, 10),
  ('tw-03', 'tailwind', 'medium', '{"uz":"Bu klasslar nima qiladi?","ru":"Что делают эти классы?","en":"What do these classes do?"}'::jsonb, '<button class="bg-blue-500 hover:bg-blue-600 focus-visible:ring-2 disabled:opacity-50">', '[{"uz":"Holat variantlari: sichqoncha ustida, klaviatura fokusida va disabled holatda turli stillar qo‘llaydi","ru":"Варианты состояний: разные стили при наведении, фокусе с клавиатуры и в состоянии disabled","en":"State variants: different styles on hover, keyboard focus and when disabled"},{"uz":"Uchta turli tugma yaratadi","ru":"Создают три разные кнопки","en":"They create three different buttons"},{"uz":"JavaScript hodisalarini qo‘shadi","ru":"Добавляют обработчики событий JavaScript","en":"They add JavaScript event handlers"},{"uz":"Faqat birinchi klass ishlaydi","ru":"Работает только первый класс","en":"Only the first class works"}]'::jsonb, 0, '{"uz":"Variant prefikslari (hover:, focus-visible:, disabled:) tegishli pseudo-klass ichida utility’ni qo‘llaydi. Ularni birlashtirish ham mumkin: md:hover:bg-blue-700.","ru":"Префиксы вариантов (hover:, focus-visible:, disabled:) применяют утилиту внутри соответствующего псевдокласса. Их можно комбинировать: md:hover:bg-blue-700.","en":"Variant prefixes (hover:, focus-visible:, disabled:) apply a utility within the matching pseudo-class. They can be stacked: md:hover:bg-blue-700."}'::jsonb, 15),
  ('tw-04', 'tailwind', 'medium', '{"uz":"Bu element turli ekranlarda qanday matn o‘lchamiga ega bo‘ladi?","ru":"Какой размер текста будет у элемента на разных экранах?","en":"What text size will this element have on different screens?"}'::jsonb, '<h1 class="text-xl lg:text-4xl">Title</h1>', '[{"uz":"Har doim text-4xl","ru":"Всегда text-4xl","en":"Always text-4xl"},{"uz":"Faqat lg ekranlarda text-xl","ru":"text-xl только на lg-экранах","en":"text-xl only on lg screens"},{"uz":"Barcha ekranlarda text-xl, lg (1024px) va undan kattada text-4xl","ru":"text-xl на всех экранах, а начиная с lg (1024px) — text-4xl","en":"text-xl on all screens, and text-4xl from lg (1024px) up"},{"uz":"Konflikt sababli hech biri ishlamaydi","ru":"Из-за конфликта не работает ни один","en":"Neither works because of the conflict"}]'::jsonb, 2, '{"uz":"Tailwind mobile-first: prefikssiz utility barcha o‘lchamlarga qo‘llanadi, breakpoint prefiksi esa shu o‘lchamdan boshlab uni qayta yozadi.","ru":"Tailwind — mobile-first: утилита без префикса действует на всех размерах, а префикс брейкпоинта переопределяет её начиная с этого размера.","en":"Tailwind is mobile-first: an unprefixed utility applies to all sizes and a breakpoint prefix overrides it from that size upward."}'::jsonb, 15),
  ('tw-05', 'tailwind', 'medium', '{"uz":"dark: varianti nima qiladi?","ru":"Что делает вариант dark:?","en":"What does the dark: variant do?"}'::jsonb, '<div class="bg-white text-slate-900 dark:bg-slate-900 dark:text-white">', '[{"uz":"Elementni har doim qorong‘i qiladi","ru":"Всегда делает элемент тёмным","en":"Always makes the element dark"},{"uz":"Qorong‘i rejim yoqilganda (prefers-color-scheme yoki .dark klassi orqali) stillarni qo‘llaydi","ru":"Применяет стили, когда включён тёмный режим (через prefers-color-scheme или класс .dark)","en":"Applies styles when dark mode is active (via prefers-color-scheme or a .dark class)"},{"uz":"Kechqurun avtomatik yoqiladi","ru":"Включается автоматически вечером","en":"Turns on automatically in the evening"},{"uz":"Rangni 50% ga qoraytiradi","ru":"Затемняет цвет на 50%","en":"Darkens the color by 50%"}]'::jsonb, 1, '{"uz":"Sukut bo‘yicha dark: tizimning prefers-color-scheme sozlamasiga bog‘liq. Qo‘lda almashtirish uchun uni class (yoki selector) strategiyasiga sozlash mumkin.","ru":"По умолчанию dark: зависит от системной prefers-color-scheme. Для ручного переключения его настраивают на стратегию класса (или селектора).","en":"By default dark: follows the system prefers-color-scheme. For a manual toggle it can be configured to a class (or selector) strategy."}'::jsonb, 15),
  ('tw-06', 'tailwind', 'hard', '{"uz":"Dizayn tizimida yo‘q bo‘lgan aniq qiymat (masalan, 327px) qanday beriladi?","ru":"Как задать точное значение, которого нет в дизайн-системе (например, 327px)?","en":"How do you apply an exact value that is not in the design system (e.g. 327px)?"}'::jsonb, null, '[{"uz":"class=\"w-327\"","ru":"class=\"w-327\"","en":"class=\"w-327\""},{"uz":"class=\"width:327px\"","ru":"class=\"width:327px\"","en":"class=\"width:327px\""},{"uz":"style=\"w-[327px]\"","ru":"style=\"w-[327px]\"","en":"style=\"w-[327px]\""},{"uz":"class=\"w-[327px]\"","ru":"class=\"w-[327px]\"","en":"class=\"w-[327px]\""}]'::jsonb, 3, '{"uz":"Kvadrat qavsli “arbitrary values” sintaksisi bir martalik qiymatlar uchun utility yaratadi: w-[327px], top-[117px], bg-[#1da1f2]. Ulardan me’yorida foydalanish kerak.","ru":"Синтаксис «arbitrary values» в квадратных скобках создаёт утилиту для разового значения: w-[327px], top-[117px], bg-[#1da1f2]. Использовать стоит умеренно.","en":"The square-bracket \"arbitrary values\" syntax generates a one-off utility: w-[327px], top-[117px], bg-[#1da1f2]. Use it sparingly."}'::jsonb, 20),
  ('tw-07', 'tailwind', 'medium', '{"uz":"@apply direktivasi nima uchun kerak?","ru":"Для чего нужна директива @apply?","en":"What is the @apply directive for?"}'::jsonb, '.btn-primary {
  @apply px-4 py-2 rounded-lg bg-indigo-600 text-white;
}', '[{"uz":"Mavjud utility’larni o‘z CSS klassingiz ichiga yig‘ish uchun","ru":"Чтобы собрать существующие утилиты внутри своего CSS-класса","en":"To compose existing utilities inside your own CSS class"},{"uz":"Klasslarni JavaScript orqali qo‘shish uchun","ru":"Чтобы добавлять классы через JavaScript","en":"To add classes via JavaScript"},{"uz":"Tailwind’ni o‘chirish uchun","ru":"Чтобы отключить Tailwind","en":"To disable Tailwind"},{"uz":"Media-so‘rov yaratish uchun","ru":"Чтобы создать медиазапрос","en":"To create a media query"}]'::jsonb, 0, '{"uz":"@apply takrorlanuvchi uslublarni (masalan, uchinchi tomon HTML’i uchun) bir joyga yig‘adi. Lekin React kabi komponent tizimlarida odatda komponentning o‘zi qayta ishlatiladi.","ru":"@apply собирает повторяющиеся стили (например, для стороннего HTML). Но в компонентных фреймворках вроде React обычно переиспользуют сам компонент.","en":"@apply bundles repeated styles (e.g. for third-party HTML). In component frameworks like React, reusing the component itself is usually better."}'::jsonb, 15),
  ('tw-08', 'tailwind', 'hard', '{"uz":"Nega bu kod kutilganidek ishlamasligi mumkin?","ru":"Почему этот код может не работать как ожидается?","en":"Why might this code not work as expected?"}'::jsonb, 'function Badge({ color }) {
  return <span className={`bg-${color}-500`}>New</span>
}', '[{"uz":"Template string’lar JSX ichida ishlamaydi","ru":"Шаблонные строки не работают в JSX","en":"Template literals do not work in JSX"},{"uz":"500 noto‘g‘ri rang darajasi","ru":"500 — неверный оттенок","en":"500 is an invalid shade"},{"uz":"Tailwind manba kodini statik skaner qiladi va dinamik yig‘ilgan klass nomlarini topa olmaydi — bu klasslar generatsiya qilinmaydi","ru":"Tailwind статически сканирует исходники и не видит динамически собранные имена классов — эти классы не генерируются","en":"Tailwind scans source files statically and cannot detect dynamically built class names — those classes are never generated"},{"uz":"className faqat string literal qabul qiladi","ru":"className принимает только строковые литералы","en":"className only accepts string literals"}]'::jsonb, 2, '{"uz":"To‘liq klass nomlarini yozing: { red: \"bg-red-500\", green: \"bg-green-500\" }[color]. Shunda skaner ularni ko‘radi va CSS’ga qo‘shadi.","ru":"Пишите полные имена классов: { red: \"bg-red-500\", green: \"bg-green-500\" }[color]. Тогда сканер их увидит и добавит в CSS.","en":"Use complete class names: { red: \"bg-red-500\", green: \"bg-green-500\" }[color]. Then the scanner sees them and includes them in the CSS."}'::jsonb, 20),
  ('tw-09', 'tailwind', 'easy', '{"uz":"p-4 klassi qancha padding beradi (standart sozlamada)?","ru":"Какой padding даёт класс p-4 (в стандартной конфигурации)?","en":"How much padding does p-4 apply (default config)?"}'::jsonb, null, '[{"uz":"4px","ru":"4px","en":"4px"},{"uz":"1rem (16px)","ru":"1rem (16px)","en":"1rem (16px)"},{"uz":"4rem","ru":"4rem","en":"4rem"},{"uz":"0.4rem","ru":"0.4rem","en":"0.4rem"}]'::jsonb, 1, '{"uz":"Tailwind spacing shkalasida 1 birlik = 0.25rem (4px). Demak, p-4 = 1rem = 16px; p-2 = 8px, p-8 = 32px.","ru":"В шкале отступов Tailwind 1 единица = 0.25rem (4px). Значит, p-4 = 1rem = 16px; p-2 = 8px, p-8 = 32px.","en":"In Tailwind''s spacing scale 1 unit = 0.25rem (4px). So p-4 = 1rem = 16px; p-2 = 8px, p-8 = 32px."}'::jsonb, 10),
